/* Generated data bundle */
window.GIFT_ORDER = ["catalyst","servant","erudite","enthusiast","host","strategist","lover"];
window.GIFTS = {"catalyst":{"slug":"catalyst","name":"The Catalyst","subtitle":"The Gift of Prophecy","metaphor":{"title":"The Volcano","description":"The volcano represents the powerful, transformative force within the prophetically gifted—a divine fire that builds pressure beneath the surface until it erupts in truth-telling and catalytic change. The color Lava Red represents this molten intensity, symbolizing the heated passion for truth and the creative and destructive potential of the gift.","icon":"Flame"},"profileSummary":"The Catalyst is a visionary and pioneering force, driven by a need for truth and a passion for revolutionary transformation. This is not merely a personality trait but a sacred calling—a divine operational style that compels them to challenge the status quo, uproot broken systems, and build new, more effective ones in their place.","foundationalVerses":["Romans 12:6 - \"Having gifts that differ according to the grace given to us, let us use them: if prophecy, in proportion to our faith.\"","1 Thessalonians 5:21 - \"Test all things; hold fast what is good.\""],"descriptiveWords":["Innovative","Challenger","Assured","Discerning","Go-getting","Adventurous"],"coreFramework":{"question":"What is the truth that will unlock transformation here?","questionDescription":"The Catalyst instinctively searches for the foundational truth that, once revealed, will catalyze change. Where others see a simple conflict, the Catalyst sees a broken system and discerns the pathway to its renewal.","energizer":"Willingness to Confront Reality","energizerDescription":"Catalysts are energized by courage, not just comfort. They need to be surrounded by people willing to look at the brutal facts of a situation and act on them.","drive":"Transformation","driveDescription":"They are compelled to spark transformation and create breakthrough solutions, acting from a sense of eternal perspective while pioneering innovative approaches that revolutionize systems."},"strengths":[{"title":"Visionary Courage","description":"They possess a profound courage that enables them to speak truth to power and challenge entrenched systems that others avoid."},{"title":"Unwavering Integrity","description":"They are driven by an uncompromising commitment to integrity and an innate desire for alignment between words, actions, and motives."},{"title":"Passionate Conviction","description":"They operate from a place of deep, immovable conviction, giving them the resilience to stand for what is right, even in the face of opposition."},{"title":"Drive for Authentic Renewal","description":"Beyond simply pointing out flaws, their ultimate strength is a powerful vision for genuine renewal and the relentless drive to help build it."}],"challenges":[{"title":"A Tendency Toward Harsh Judgment","description":"Their high standards can cause them to judge others' perceived failures without sufficient grace."},{"title":"Impatience with Process","description":"Their breakneck desire for results can cause them to view other personalities as barriers to change."},{"title":"Emotional Burden and Isolation","description":"The constant awareness of what's wrong can create a heavy emotional burden, leading to cynicism and isolation if not balanced with grace."}],"leadershipStyle":{"title":"Catalytic Innovator","description":"Prophetic leaders lead through transformational vision and breakthrough thinking.","characteristics":["Disruptive Innovation","Catalytic Communication","Pioneering Spirit","Systems Transformation","Moral Courage"]},"interactions":["Be direct and willing to confront hard truths; they value courage over comfort.","Focus on the \"why\" behind a project, not just the \"what.\"","Give them problems to solve and a safe place to fail without judgment.","Don't be offended by their directness; understand it often comes from a desire to improve things."],"commission":"Jeremiah 1:10: \"See, today I appoint you over nations and kingdoms to uproot and tear down, to destroy and overthrow, to build and to plant.\"","pressure":{"trigger":"Being asked to pretend. The Catalyst descends when the truth in the room is obvious to them and unspeakable to everyone else, or when the words people say and the things they do stop matching and no one will name it.","flare":["Sharpen","Indict","Scorch"],"signature":"Sharpen · Indict · Scorch","descent":[{"stage":"Strain","verb":"Sharpen","tell":"Every observation acquires an edge.","body":"The Catalyst is still saying true things, but the truth has stopped being offered and started being delivered. Questions become tests. Praise gets a clause attached to it. They are not trying to wound anyone yet — they are trying to be heard, and volume is the only lever they can find.","cost":"People start pre-editing what they bring to this person, which removes exactly the raw information the Catalyst needs to do their work."},{"stage":"Distortion","verb":"Indict","tell":"The problem stops being the system and becomes the people.","body":"Motives get assigned. What was a critique of a broken process becomes a verdict on someone's character, delivered with the certainty the Catalyst normally reserves for facts. They are now prosecuting rather than diagnosing, and they experience the pushback as further proof that everyone is compromised.","cost":"The Catalyst begins to be right about the wrong thing. The accuracy of the original insight gets buried under the injustice of the accusation, and no one can access the truth anymore."},{"stage":"Captivity","verb":"Scorch","tell":"Burning it down starts to feel like faithfulness.","body":"Nothing is redeemable. The Catalyst exits, detonates, or dismantles — the relationship, the role, the institution — and reads the wreckage as integrity. Cynicism has replaced discernment, and because cynicism is never technically wrong about anything, it is almost impossible to argue with from the inside.","cost":"The gift meant for renewal has done only demolition. The Catalyst is left isolated with an intact conviction and nothing built."}],"chronic":{"name":"The Prosecutor","body":"Every conversation becomes a case being made. The Catalyst is no longer looking for what is true; they are gathering evidence. Relationships become witnesses, and everyone learns to testify carefully."},"needs":"Evidence that the truth actually landed somewhere. Not agreement — reception. And congruence: people whose actions match their words.","sayThis":"You're not wrong about this. Tell me what you see, and then tell me what you want done with it.","notThis":"You're being too intense.","notThisWhy":"It confirms the Catalyst's deepest fear — that telling the truth costs them belonging. They will either escalate to be heard or leave to stop needing to be.","ownMove":"Separate the truth from the verdict. Name the problem out loud without assigning the motive behind it. The Catalyst's power is diagnostic, and a diagnosis stops working the moment it becomes an accusation.","restored":"Courage","restoredBody":"The willingness to say the hard thing for someone rather than at them — which is the only form of prophetic speech anyone can actually receive."}},"servant":{"slug":"servant","name":"The Servant of All","subtitle":"The Gift of Service","metaphor":{"title":"The Harvester","description":"The harvester represents the tireless, systematic work of gathering what has been planted. Like a combine harvester moving through fields with precision and endurance, those with the gift of service work with methodical excellence to meet practical needs and ensure nothing valuable is wasted.","icon":"Wrench"},"profileSummary":"The Servant of All possesses a divine compulsion to meet practical needs through tangible action and faithful work. They are the backbone of any organization, driven not by recognition but by the deep satisfaction of seeing tasks completed with excellence and people genuinely helped.","foundationalVerses":["Romans 12:7 - \"If it is serving, then serve; if it is teaching, then teach.\"","Mark 10:43-44 - \"Whoever wants to become great among you must be your servant, and whoever wants to be first must be slave of all.\""],"descriptiveWords":["Industrious","Hands-on","Consistent","Meticulous","Supportive","Conscientious"],"coreFramework":{"question":"What needs to be done, and who is doing it?","questionDescription":"The service-gifted are driven by an internal question that constantly scans their environment for practical needs and assesses whether everyone is contributing fairly.","energizer":"Visible Recognition & Shared Effort","energizerDescription":"They are energized when their practical contributions are specifically noticed and genuinely recognized, and they thrive when others step up to help.","drive":"Tangible Results","driveDescription":"They are driven by the deep satisfaction of completing a task, solving a practical problem, and seeing the high-quality result of their labor."},"strengths":[{"title":"Unwavering Dependability","description":"They possess a rare level of reliability that others can count on. When they commit to something, it gets done with excellence and on time."},{"title":"Excellence in Execution","description":"They have a natural drive for quality and attention to detail that ensures work is not just completed but completed well."},{"title":"Practical Problem-Solving","description":"They excel at finding practical, effective solutions to real-world problems and implementing them efficiently."},{"title":"Faithful Endurance","description":"They possess the perseverance to stick with tasks through completion, even when the work is difficult or unrecognized."}],"challenges":[{"title":"Tendency to Over-Commit","description":"Their desire to help can lead them to take on more than they can handle, resulting in burnout and resentment."},{"title":"Difficulty Saying No","description":"They may struggle to set healthy boundaries and prioritize their own needs when others are asking for help."},{"title":"Criticism of Others' Work Standards","description":"Their high standards for quality work can lead to frustration and criticism when others don't meet their expectations."}],"leadershipStyle":{"title":"Servant Leader","description":"Service leaders lead through humble example and dedicated support.","characteristics":["Leading by Example","Practical Problem-Solving","Supportive Infrastructure","Attention to Detail","Consistent Follow-Through"]},"interactions":["Appreciate their behind-the-scenes work and acknowledge their contributions.","Give them clear expectations and the resources they need to do excellent work.","Don't take advantage of their willingness to help; respect their time and energy.","Include them in planning so they understand how their work fits into the bigger picture."],"commission":"Mark 10:43-44: \"Whoever wants to become great among you must be your servant, and whoever wants to be first must be slave of all.\"","pressure":{"trigger":"Invisibility. The Servant descends when the work is real, the cost is real, and no one has noticed either — or when help that was freely offered starts being quietly expected.","flare":["Absorb","Tally","Collapse"],"signature":"Absorb · Tally · Collapse","descent":[{"stage":"Strain","verb":"Absorb","tell":"The list grows and the request never comes.","body":"Rather than ask for help or name a limit, the Servant simply takes on more. They are still glad to do it, mostly. But the yes has started to be automatic rather than chosen, and somewhere underneath it a quiet arithmetic has begun.","cost":"Everyone around them recalibrates upward. The Servant's capacity becomes the new baseline expectation, and the very reliability that makes them valuable makes their limit invisible."},{"stage":"Distortion","verb":"Tally","tell":"The help develops a bill attached to it.","body":"The scorekeeping surfaces — never as a direct statement, always as a sigh, a pointed aside, a martyred comment made half-joking. Service becomes leverage. The Servant would be horrified to hear it described this way, because from inside it feels like nothing more than wanting to be seen.","cost":"Gratitude becomes impossible to give. Anything offered now reads as payment on a debt, so even genuine thanks fails to satisfy, which proves to the Servant that no one really values them."},{"stage":"Captivity","verb":"Collapse","tell":"The breakdown, and the blame that follows it.","body":"The body or the will finally gives out, and the resentment that has been accumulating for years arrives all at once — aimed at the exact people the Servant spent themselves serving. Self-pity and bitterness braid together into a story in which they were used, and everyone else was the user.","cost":"The relationships the work was meant to build are the relationships the collapse destroys. Years of genuine faithfulness get retroactively reinterpreted as exploitation."}],"chronic":{"name":"The Ledger","body":"Every act of service becomes an entry someone owes. The Servant keeps the books privately and perfectly, and no one else knows they are in debt — which means no one can ever pay."},"needs":"To be thanked for something specific rather than in general. To be asked rather than assumed. And explicit permission to stop.","sayThis":"I saw what you did, and I know what it cost you. What can I take off your plate?","notThis":"You didn't have to do that.","notThisWhy":"It is meant as absolution and lands as erasure. The Servant already paid the cost; being told it was unnecessary makes the payment meaningless rather than making it lighter.","ownMove":"Say the tally out loud. Ask directly for the thing you have been silently keeping score of. A ledger only has power while it is private — spoken, it turns back into an ordinary request that someone can actually grant.","restored":"Faithfulness","restoredBody":"Work offered freely rather than banked — the kind of steady, unglamorous competence that holds up everything else and asks for nothing but honesty in return."}},"erudite":{"slug":"erudite","name":"The Erudite","subtitle":"The Gift of Teaching","metaphor":{"title":"The Ancient Oak Tree","description":"The Ancient Oak represents the deep-rooted wisdom and enduring strength of the teaching gift. Like an oak that grows slowly but stands for centuries, those with the gift of teaching develop profound understanding over time and become sources of reliable wisdom for generations.","icon":"TreePine"},"profileSummary":"The Erudite carries a divine hunger for truth and understanding, called to learn with rigor and share knowledge with clarity. They are driven by an insatiable curiosity and a commitment to intellectual honesty that makes them trusted sources of wisdom and insight.","foundationalVerses":["Romans 12:7 - \"If it is serving, then serve; if it is teaching, then teach.\"","2 Timothy 2:15 - \"Study to show yourself approved to God, a worker who does not need to be ashamed and who correctly handles the word of truth.\""],"descriptiveWords":["Analytical","Thorough","Patient","Precise","Knowledgeable","Insightful"],"coreFramework":{"question":"Is this subject worthy of my intellectual energy?","questionDescription":"The Erudite filters the world through a lens of intellectual substance. Before investing their energy, they instinctively assess if a topic has sufficient depth and truth to justify the rigorous process of mastery.","energizer":"Deep Study & Genuine Curiosity from Others","energizerDescription":"They are energized by uninterrupted time for deep research and reflection. This energy is compounded when others show genuine curiosity and a sincere desire to learn what they have discovered.","drive":"To Acquire & Disseminate Knowledge","driveDescription":"They are driven by an insatiable desire to acquire a mastery-level understanding of complex subjects and feel a compulsion to disseminate that knowledge with clarity and precision."},"strengths":[{"title":"Intellectual Rigor","description":"They possess an exceptional commitment to thorough research and logical analysis that ensures their conclusions are well-founded and trustworthy."},{"title":"Patient Teaching Ability","description":"They have a natural gift for breaking down complex concepts and presenting them in ways that others can understand and apply."},{"title":"Commitment to Accuracy","description":"They are driven by a desire for precision and truth that makes them reliable sources of information and wisdom."},{"title":"Deep Curiosity","description":"They possess an insatiable hunger for learning that drives them to continuously expand their knowledge and understanding."}],"challenges":[{"title":"Analysis Paralysis","description":"Their desire for thoroughness can sometimes prevent them from taking action or making decisions in a timely manner."},{"title":"Impatience with Shallow Thinking","description":"They may become frustrated with others who don't share their commitment to intellectual rigor and deep analysis."},{"title":"Tendency to Intellectualize Emotions","description":"They may struggle to connect with others on an emotional level, preferring logical analysis over emotional processing."}],"leadershipStyle":{"title":"The Wise Teacher","description":"Erudite leaders lead through wisdom, clarity, and the intellectual development of their team. They don't just give answers; they teach people how to think.","characteristics":["Mentoring Focus","Clarity of Communication","Evidence-Based Decisions","Fostering a Learning Culture","Principled Guidance"]},"interactions":["Respect their need for time to think and research before making decisions.","Value their expertise and seek their input on complex matters.","Don't rush them into quick decisions; they need time to analyze properly.","Appreciate their commitment to accuracy and thoroughness."],"commission":"Matthew 28:19-20: \"Go therefore and make disciples of all nations... teaching them to observe all that I have commanded you.\"","pressure":{"trigger":"Being rushed, or being simplified. The Erudite descends when they are pushed to conclude before they have grounds, or when their carefulness is treated as an obstacle rather than a contribution.","flare":["Qualify","Correct","Seal"],"signature":"Qualify · Correct · Seal","descent":[{"stage":"Strain","verb":"Qualify","tell":"The answer arrives wrapped in so many conditions that it stops being an answer.","body":"The Erudite hedges, footnotes, and defers. They will not commit until the case is airtight, and the case is never quite airtight. What presents as rigor is increasingly self-protection: an unqualified statement is a statement that can be wrong.","cost":"The room stops asking. The most carefully considered perspective available goes unheard because it never arrives in a usable form, and the Erudite reads the silence as confirmation that no one values depth."},{"stage":"Distortion","verb":"Correct","tell":"Accuracy becomes a weapon.","body":"Being right stops being a service and starts being a position. The Erudite catches errors precisely, at the moment they will cost the other person the most, and defends the correction as intellectual honesty. Rigidity sets in — the standard hardens into law, and grace becomes indistinguishable from sloppiness.","cost":"They win points and lose people. Each victory makes the next conversation more guarded, and the Erudite ends up with the last word and no one left in the argument."},{"stage":"Captivity","verb":"Seal","tell":"The door closes, and the silence does the punishing.","body":"The Erudite withdraws behind the wall of being right and stops coming out. Absence becomes the discipline they administer to a world that would not slow down for them. Any attempt to reach them registers as intrusion, so the reaching stops, which proves the withdrawal was warranted.","cost":"A mind built to illuminate now only archives. The Erudite is unreachable, entirely certain, and completely alone with the truth."}],"chronic":{"name":"The Citadel","body":"Correctness becomes a place to live rather than a thing to offer. The walls are real, the defenses are excellent, and no one has been inside in years."},"needs":"Time before a decision, and space that is not read as rejection. To be asked for their depth rather than for the short version of it.","sayThis":"I want your read on this. Take the time you need — just tell me when you'll have it.","notThis":"Can you just give me the bottom line?","notThisWhy":"It tells the Erudite that their entire process is overhead. They will either withhold the analysis or deliver it in a form designed to prove the process was necessary.","ownMove":"Offer the partial answer before it is finished, and label it as partial. Being useful now beats being unassailable later, and a clearly-flagged provisional read costs you nothing in credibility.","restored":"Wisdom","restoredBody":"Knowledge delivered at the speed a person can actually receive it — depth in service of someone else's understanding rather than in defense of your own."}},"enthusiast":{"slug":"enthusiast","name":"The Enthusiast","subtitle":"The Gift of Encouragement","metaphor":{"title":"The Magnet","description":"The magnet represents the natural ability to attract and connect people through positive energy and genuine care. Like a magnet that draws metal filings into alignment, those with the gift of encouragement have a remarkable ability to draw people together and align them toward common goals.","icon":"Users"},"profileSummary":"The Enthusiast operates under a divine mandate to champion the potential in others and foster meaningful connections. They are natural connectors and motivators, driven by a genuine love for people and an unshakeable belief in their capacity to grow and succeed.","foundationalVerses":["Romans 12:8 - \"If it is to encourage, then give encouragement.\"","1 Thessalonians 5:11 - \"Therefore encourage one another and build each other up, just as in fact you are doing.\""],"descriptiveWords":["Enthusiastic","Rallying","Expressive","Affirming","Motivational","Interpersonal"],"coreFramework":{"question":"Are we building a bond?","questionDescription":"The Enthusiast constantly assesses the quality of relational connection, believing that authentic connection is the foundation for all positive growth.","energizer":"Heartfelt Connection & Shared Joy","energizerDescription":"They are energized by moments of authentic connection—shared laughter, meaningful conversation, and mutual celebration.","drive":"To Rally","driveDescription":"They are driven by an innate ability to rally people together around a shared purpose or possibility, turning individual potential into group momentum."},"strengths":[{"title":"Natural Motivational Ability","description":"They possess an extraordinary gift for inspiring others and helping them believe in their own potential and possibilities."},{"title":"Relationship Building","description":"They excel at creating meaningful connections between people and fostering environments of trust and collaboration."},{"title":"Positive Energy","description":"They bring an infectious optimism and enthusiasm that lifts the spirits of those around them and creates positive momentum."},{"title":"Ability to See Potential","description":"They have a remarkable ability to see the best in people and help them recognize and develop their own gifts and capabilities."}],"challenges":[{"title":"Avoiding Difficult Conversations","description":"Their desire to maintain positive relationships can lead them to avoid necessary but challenging conversations."},{"title":"Over-Optimism","description":"Their positive outlook can sometimes lead them to overlook real problems or minimize legitimate concerns."},{"title":"People-Pleasing Tendencies","description":"They may struggle to set boundaries or make decisions that might disappoint others, even when those decisions are necessary."}],"leadershipStyle":{"title":"Inspirational Motivator","description":"Enthusiast leaders lead through inspiration and empowerment.","characteristics":["Vision Casting","Strength-Based Development","Positive Culture Creation","Recognition and Celebration","Coaching and Mentoring","Empowerment"]},"interactions":["Appreciate their efforts to maintain positive relationships and team morale.","Help them balance optimism with realistic assessment of challenges.","Support them in having difficult conversations when necessary.","Value their ability to see potential in others and build strong teams."],"commission":"Hebrews 10:24: \"And let us consider how we may spur one another on toward love and good deeds.\"","pressure":{"trigger":"Disconnection. The Enthusiast descends when the relational bond feels at risk — when a room goes cold, when a conflict has no visible resolution, or when they suspect they are valued for the energy they supply rather than for who they are.","flare":["Perform","Spin","Vanish"],"signature":"Perform · Spin · Vanish","descent":[{"stage":"Strain","verb":"Perform","tell":"The energy goes up and the substance goes down.","body":"The Enthusiast fills the silence, amplifies the story, and works the room harder. Every gap gets a joke in it. They are not being dishonest — they are managing an anxiety they may not have named, and the tool they reach for is the one they are best at.","cost":"The performance succeeds and the person disappears behind it. The Enthusiast becomes the most visible and least known person in the room, which deepens exactly the isolation driving the behavior."},{"stage":"Distortion","verb":"Spin","tell":"The hard thing gets reframed until it no longer has to be faced.","body":"Charm turns into management. The Enthusiast redirects, softens, and finds the angle that makes the difficult conversation unnecessary — sometimes with a formula or a slogan standing in where a real solution belongs. Under enough pressure they will start assigning blame elsewhere, because the alternative is holding it.","cost":"Problems get postponed rather than solved, and the people around them stop trusting the reassurance. Warmth that consistently precedes avoidance eventually stops reading as warmth."},{"stage":"Captivity","verb":"Vanish","tell":"The exit, framed as freedom.","body":"The Enthusiast leaves — the job, the church, the friendship — often abruptly and often with a story about how constricting it had become. Underneath the story is a conviction they may never say out loud: that they were never actually wanted, only enjoyed, and that leaving first is cheaper than being left.","cost":"A gift built to bind people together produces a life of unfinished relationships, each ended just before it could be tested."}],"chronic":{"name":"The Performance","body":"The room always gets the show and never gets the person. The Enthusiast is universally liked, thoroughly enjoyed, and known by almost no one — including, increasingly, themselves."},"needs":"To be wanted for who they are rather than for what they bring. Evidence that the relationship survives a hard conversation.","sayThis":"I'm not going anywhere. We can sit in this until it's actually resolved.","notThis":"Can you be serious for once?","notThisWhy":"It tells the Enthusiast that their gift is the problem. They will either perform harder to win back approval or quietly write the relationship off as one more place they don't fit.","ownMove":"Stay in the room after the energy runs out. Let one conversation be flat, unresolved, and unlit — and notice that no one leaves. The proof you need cannot be generated by the performance; it can only be found on the other side of stopping it.","restored":"Encouragement","restoredBody":"Hope offered out of substance rather than out of performance — the kind that holds up because the person offering it stayed for the hard part."}},"host":{"slug":"host","name":"The Host","subtitle":"The Gift of Giving","metaphor":{"title":"The Silo","description":"The silo represents the strategic storage and distribution of resources for maximum impact. Like a grain silo that preserves harvest abundance for future seasons, those with the gift of giving understand how to steward resources wisely and release them strategically for the greatest benefit.","icon":"Building"},"profileSummary":"The Host understands that all resources are entrusted to them for the benefit of others through strategic stewardship. They are driven not by accumulation but by multiplication—finding ways to use what they have been given to empower others and create sustainable impact.","foundationalVerses":["Romans 12:8 - \"If it is giving, then give generously.\"","Luke 6:38 - \"Give, and it will be given to you. A good measure, pressed down, shaken together and running over, will be poured into your lap. For with the measure you use, it will be measured to you.\""],"descriptiveWords":["Generous","Multiplier","Hospitable","Prudent","Empowering","Abundant"],"coreFramework":{"question":"How are we stewarding our resources?","questionDescription":"The Host constantly evaluates how they and others are managing what they've been entrusted with, assessing whether resources are being used wisely and strategically.","energizer":"Fruitful Impact & Expressed Gratitude","energizerDescription":"Hosts are energized when they see their resources making a real, tangible difference in others' lives and when their thoughtful giving is met with genuine gratitude.","drive":"To Steward & Multiply","driveDescription":"They are driven to create, manage, and multiply resources so they can give more generously and effectively, and to help others become good stewards as well."},"strengths":[{"title":"Strategic Generosity","description":"They possess an exceptional ability to give in ways that create maximum impact and empower others to succeed and give in return."},{"title":"Resource Wisdom","description":"They have a natural understanding of how to manage, preserve, and multiply resources for long-term benefit rather than short-term gratification."},{"title":"Empowerment Focus","description":"They excel at using their resources to empower others, creating opportunities for people to develop their own capabilities and become successful."},{"title":"Multiplication Mindset","description":"They think in terms of creating systems and opportunities that multiply impact rather than simply meeting immediate needs."}],"challenges":[{"title":"Tendency to Control Outcomes","description":"Their strategic approach to giving can sometimes lead them to try to control how their gifts are used rather than trusting the recipients."},{"title":"Difficulty with Spontaneous Giving","description":"Their preference for strategic planning can make it challenging for them to respond to immediate, unplanned needs with flexibility."},{"title":"Judgment of Poor Stewardship","description":"They may become frustrated with others who don't share their commitment to wise resource management and strategic thinking."}],"leadershipStyle":{"title":"The Steward Leader","description":"Host leaders lead through resource provision and strategic investment.","characteristics":["Resource Provision","Strategic Investment","Opportunity Creation","Welcoming Culture","Empowerment Focus","Stewardship Modeling"]},"interactions":["Respect their desire to understand how resources will be used before committing.","Show them the long-term impact and multiplication potential of projects.","Don't pressure them for immediate decisions; they need time to consider strategic implications.","Appreciate their commitment to wise stewardship and empowerment of others."],"commission":"Acts 20:35: \"It is more blessed to give than to receive.\"","pressure":{"trigger":"Being treated as a source rather than a person. The Host descends when what they provide is consumed without acknowledgment, when generosity gets taken for granted, or when they cannot see any fruit from what they gave.","flare":["Ration","Leverage","Withhold"],"signature":"Ration · Leverage · Withhold","descent":[{"stage":"Strain","verb":"Ration","tell":"Generosity develops conditions.","body":"The Host begins measuring — quietly, and with real precision — what goes out against what comes back. Gifts still get given, but they are now being weighed first. Prudence is the language used for it, and prudence is a genuine part of this gift, which is what makes the shift so hard to catch.","cost":"The freedom drains out of the giving while the giving continues. Recipients feel the change before anyone can name it, and the warmth that made the provision meaningful starts to cool."},{"stage":"Distortion","verb":"Leverage","tell":"The gift becomes a lever.","body":"Provision starts purchasing compliance. There are strings, and everyone can feel them even when no one names them — the trip, the tuition, the job, the check, each carrying an unstated expectation about behavior or loyalty. The Host would call this stewardship. The people receiving it call it something else, privately.","cost":"Every future gift becomes suspect. Genuine generosity can no longer be received as generosity, because no one can tell anymore which offers have a hook in them."},{"stage":"Captivity","verb":"Withhold","tell":"The hand closes, and stays closed.","body":"The Host shuts down the flow entirely — resources, hospitality, warmth, presence — and calls it wisdom. They hoard, isolate, and build a case for why no one deserved it anyway. The gift that was meant to circulate has become a vault with the owner locked inside it.","cost":"Abundance without any joy in it. The Host ends with everything they gathered and no one they gathered it for."}],"chronic":{"name":"The Vault","body":"A hand that was made to open has learned to stay shut. What remains is accumulation without circulation, and a growing conviction that generosity was always naïve."},"needs":"To see the fruit of what they gave. To be received as a person and not only as a resource.","sayThis":"Here's what your investment actually made possible. And separately — how are you doing?","notThis":"Opening with 'can you cover this?'","notThisWhy":"It confirms that they are a mechanism rather than a member. Every request that arrives before a relationship does moves the Host one notch toward the vault.","ownMove":"Give one thing with no expectation of return and tell no one you did it. The ledger loses its grip the moment you prove to yourself that you can operate without it.","restored":"Generosity","restoredBody":"An open hand that is not paying for anything — provision offered because it is good, not because it secures something."}},"strategist":{"slug":"strategist","name":"The Strategist","subtitle":"The Gift of Leadership","metaphor":{"title":"The Ship's Helm","description":"The ship's helm represents the steady, purposeful guidance that keeps an organization moving toward its destination despite changing winds and currents. Like a skilled helmsman who reads both the immediate conditions and the distant horizon, those with the gift of leadership navigate toward long-term vision while managing present realities.","icon":"Compass"},"profileSummary":"The Strategist carries a divine capacity to see future possibilities and architect the systems required to make them reality. They are natural visionaries and systematic builders, driven by the ability to envision what could be and the determination to create the pathways to achieve it.","foundationalVerses":["Romans 12:8 - \"If it is to lead, do it diligently.\"","Proverbs 29:18 - \"Where there is no vision, the people perish.\""],"descriptiveWords":["Decisive","Goal-oriented","Authoritative","Systematic","Developmental","Architectural"],"coreFramework":{"question":"Where are we going, and what is the best way to get there?","questionDescription":"The Strategist sees the world through a lens of vision and execution, instinctively assessing the ultimate goal and then architecting the most effective path to achieve it.","energizer":"Team Alignment & Measurable Progress","energizerDescription":"They are energized when the team is aligned with the vision and working together cohesively. Seeing measurable progress toward clear objectives fuels their drive.","drive":"To Architect Success","driveDescription":"They are compelled to provide direction, create order from chaos, and build systems that produce sustainable excellence, developing people and frameworks that succeed long-term."},"strengths":[{"title":"Visionary Thinking","description":"They possess an exceptional ability to envision future possibilities and see the big picture in ways that others cannot."},{"title":"Systems Architecture","description":"They excel at designing and implementing systematic approaches that turn visions into achievable, step-by-step realities."},{"title":"Strategic Decision-Making","description":"They have a natural ability to make decisions that align with long-term objectives rather than just addressing immediate concerns."},{"title":"Development of Others","description":"They are gifted at recognizing potential in others and creating opportunities for people to grow and contribute to larger objectives."}],"challenges":[{"title":"Impatience with Details","description":"Their focus on big-picture vision can sometimes lead them to overlook important details or become impatient with necessary but mundane tasks."},{"title":"Tendency to Overwhelm Others","description":"Their ambitious visions and systematic approaches can sometimes feel overwhelming or unrealistic to others who don't share their strategic perspective."},{"title":"Difficulty with Immediate Needs","description":"Their long-term focus can make it challenging for them to respond effectively to immediate, urgent needs that don't fit into their strategic plans."}],"leadershipStyle":{"title":"Strategic Architect","description":"Strategist leaders lead through vision, planning, and systematic execution.","characteristics":["Visionary Planning","Strategic Thinking","System Building","Team Development","Goal Achievement"]},"interactions":["Respect their need to understand how immediate tasks fit into the bigger picture.","Support their long-term thinking and don't pressure them for quick fixes to complex problems.","Help them communicate their vision in ways that others can understand and embrace.","Appreciate their commitment to systematic development and sustainable growth."],"commission":"Proverbs 29:18: \"Where there is no vision, the people perish; but blessed is he who keeps the law.\"","pressure":{"trigger":"Loss of control over the outcome. The Strategist descends when the plan is undermined, when commitments quietly go unmet, or when they are held responsible for a result they were not given the authority to secure.","flare":["Tighten","Override","Freeze"],"signature":"Tighten · Override · Freeze","descent":[{"stage":"Strain","verb":"Tighten","tell":"The grip closes on the plan.","body":"Delegation either stops or becomes assignment without trust — tasks handed out with the outcome already specified and the judgment withheld. The Strategist starts driving themselves harder than anyone and expecting the same, and begins to read as cold to people who were used to being led rather than deployed.","cost":"Ownership evaporates. People execute instructions instead of pursuing goals, which produces exactly the mediocrity that made the Strategist tighten in the first place."},{"stage":"Distortion","verb":"Override","tell":"People become resources to be spent.","body":"The Strategist rolls over objections to protect the plan. Sarcasm replaces persuasion because persuasion takes time they no longer believe they have. Human costs get logged as acceptable losses, and the mission becomes the justification for how the mission is being pursued.","cost":"The best people stop arguing, then stop caring, then leave. The Strategist wins the objective and loses the team that could have held it."},{"stage":"Captivity","verb":"Freeze","tell":"Total self-reliance, experienced as strength.","body":"Trust is gone. The Strategist runs everything alone, keeps their own counsel, and treats the resulting isolation as evidence of superior capability rather than as a symptom. Suspicion becomes the default posture, and the drivenness often migrates into the body — work, stimulants, punishing routines, anything that keeps the engine loud enough to drown the rest out.","cost":"A gift built to carry people ends up carrying everything alone. The load is real, the competence is real, and no one is left to share either."}],"chronic":{"name":"The Command","body":"Relationship collapses into chain of command. Everyone knows their assignment and no one knows the Strategist, including the people who report to them every day."},"needs":"Genuine agreement on the plan, or an honest renegotiation of it. Not silent non-compliance, which is the one thing they cannot work with.","sayThis":"I'm with you on the plan. Here's the one part I need to change, and here's why.","notThis":"Let's just see how it goes.","notThisWhy":"It reads as abandonment of the mission. The Strategist hears that no one else is holding the outcome, and takes the whole weight back onto themselves.","ownMove":"Ask one person what they think before you decide — and let the answer actually move the plan. Not consultation as theater. A plan that no one was allowed to shape is a plan no one will carry when you are not watching.","restored":"Diligence","restoredBody":"Leadership that carries people rather than spends them — the long, patient discipline of getting somewhere with everyone still aboard."}},"lover":{"slug":"lover","name":"The Lover","subtitle":"The Gift of Mercy","metaphor":{"title":"The Heart","description":"The heart represents the life-giving center of compassion and emotional healing. Like the physical heart that pumps life-sustaining blood throughout the body, those with the gift of mercy circulate love, empathy, and healing throughout their communities, bringing emotional health and restoration.","icon":"Heart"},"profileSummary":"The Lover carries a divine heart that beats with compassion for the suffering and wounded, bringing healing presence wherever pain exists. They are natural empaths and healers, driven by an overwhelming desire to comfort, protect, and restore those who are hurting.","foundationalVerses":["Romans 12:8 - \"If it is to show mercy, do it cheerfully.\"","2 Corinthians 1:3-4 - \"Praise be to the God and Father of our Lord Jesus Christ, the Father of compassion and the God of all comfort, who comforts us in all our troubles, so that we can comfort those in any trouble with the comfort we ourselves receive from God.\""],"descriptiveWords":["Empathetic","Accepting","Nurturing","Rescuing","Gentle","Patient"],"coreFramework":{"question":"Is this a safe place for the heart?","questionDescription":"The Lover constantly assesses the emotional climate of their surroundings, driven to create environments where hearts can be vulnerable without fear of judgment.","energizer":"Emotional Safety & Unconditional Acceptance","energizerDescription":"Lovers are energized by authentic, intimate relationships where they are loved and accepted for who they are, not just what they do. They thrive in environments of emotional honesty and gentle communication where they can offer and receive comfort freely.","drive":"To Comfort, Rescue, and Shield","driveDescription":"They are compelled to bring emotional comfort to those who are hurting, rescue those trapped in pain, and shield the vulnerable from further harm."},"strengths":[{"title":"Deep Empathy","description":"They possess an extraordinary ability to understand and share in the emotions of others, creating profound connections and offering genuine comfort."},{"title":"Healing Presence","description":"They have a natural gift for creating safe emotional spaces where people can process pain and begin to heal from their wounds."},{"title":"Unconditional Acceptance","description":"They excel at offering love and acceptance without judgment, helping others feel valued and worthy regardless of their circumstances."},{"title":"Protective Instincts","description":"They are naturally driven to protect others from emotional harm and to intervene when they see injustice or cruelty."}],"challenges":[{"title":"Emotional Overwhelm","description":"Their deep empathy can lead them to absorb others' pain to an unhealthy degree, resulting in emotional exhaustion and burnout."},{"title":"Difficulty with Boundaries","description":"Their desire to help everyone can make it challenging for them to set healthy limits and protect their own emotional well-being."},{"title":"Avoidance of Necessary Confrontation","description":"Their preference for harmony and emotional safety can lead them to avoid necessary but difficult conversations or decisions."}],"leadershipStyle":{"title":"Compassionate Shepherd","description":"Mercy leaders lead through care, understanding, and creating safe environments.","characteristics":["Pastoral Care","Safe Environment Creation","Patient Development","Conflict Resolution","Supportive Presence"]},"interactions":["Create emotionally safe environments where they can be vulnerable without judgment.","Appreciate their gift for understanding and comforting others in pain.","Help them maintain healthy boundaries and avoid emotional overwhelm.","Support them in learning to balance mercy with necessary accountability."],"commission":"Luke 6:36: \"Be merciful, just as your Father is merciful.\"","pressure":{"trigger":"Rejection, or the suspicion of it. The Lover descends when acceptance feels conditional, when conflict goes unrepaired, or when they sense that their inner world is too much for the people around them.","flare":["Soothe","Plead","Shut Down"],"signature":"Soothe · Plead · Shut Down","descent":[{"stage":"Strain","verb":"Soothe","tell":"The room gets smoothed, and the cost gets absorbed.","body":"The Lover agrees to things they do not agree with, apologizes for things that were not theirs, and takes the tension of the room into their own body so no one else has to hold it. Their own need goes unspoken because speaking it might introduce friction, and friction is the thing they are working hardest to prevent.","cost":"The peace is real and it is being purchased with the Lover's self. No one knows the price is being paid, so no one thinks to stop it."},{"stage":"Distortion","verb":"Plead","tell":"The hurt starts leaking out sideways.","body":"Over-explaining. Testing for reassurance. Long accounts of what happened that are really a request to be told they are still wanted. The Lover has too much feeling and no direct channel for it, so it comes out as confusion, defensiveness, or a hurt that everyone senses and no one can locate.","cost":"The people around them respond to the symptom rather than the need — reassuring the surface while the actual question goes unasked and unanswered."},{"stage":"Captivity","verb":"Shut Down","tell":"A quiet that is not peace.","body":"The Lover goes still and unreachable, having concluded something that feels less like a thought than a fact: that they were never really wanted, only tolerated. Bitterness and unforgiveness settle in underneath the quiet, and the door that stays closed is the same door they spent years holding open for everyone else.","cost":"The most relationally gifted person in the room becomes the least reachable. And because the shutdown is silent, it is frequently mistaken for being fine."}],"chronic":{"name":"The Erasure","body":"The self dissolves into everyone else's comfort. The Lover is present in the room and absent from it, endlessly accommodating and quietly waiting to be noticed by someone who has been given no reason to look."},"needs":"Acceptance that does not have to be earned, and to be told directly — in words, not inference — that they are wanted.","sayThis":"I want you here. Not because of what you do for us. I want you.","notThis":"You're overreacting.","notThisWhy":"It confirms the fear underneath everything: that their inner world is too much, and that feeling deeply is a defect rather than the gift itself.","ownMove":"Say the unsmoothed thing. Name one need with no apology attached to the front of it and no justification attached to the back. The relationships worth having will hold it, and you cannot find out which ones those are while you are protecting everyone from you.","restored":"Compassion","restoredBody":"Mercy given out of fullness rather than out of fear — the kind that can stay present to someone else's pain because it is no longer trying to earn a place in the room."}}};
window.ARCHETYPES = [{"num":1,"name":"The Apex Visionary","slug":"apex-visionary","gifts":["catalyst","erudite","strategist"],"pressure":{"name":"The Sealed Blueprint","line":"A complete design no one was allowed to shape, defended by someone who has stopped believing anyone could.","missing":{"gift":"lover","text":"Mercy is the brake this archetype does not have. A Lover registers that the room went quiet three meetings ago — the one datum that would have shown the model was losing the people it was built for."},"pattern":"amplifying","stages":[{"text":"The vision acquires an edge, the evidence acquires caveats, and the plan acquires a tighter grip — all in the same week. Colleagues meet someone simultaneously more urgent, less forthcoming and less willing to delegate, and read it as a door closing while the demands rise."},{"text":"Every objection now meets three walls at once: a challenge to the objector's motives, a correction of their facts, and a decision already taken without them. There is no angle left from which to disagree, because each route has been separately foreclosed."},{"text":"One gift burns the institution, one walls off the reasoning, one severs the relationships. All three feel like integrity from the inside, and the resulting isolation gets read as confirmation rather than as symptom."}],"tell":"Watch the delegation, not the intensity. When this archetype stops handing off pieces of the design, the other two descents are already underway."},"essence":"To pioneer a transformative possibility, establish its intellectual credibility, and design the long-range architecture through which it can reshape the future.","section":"Section 1: The Apex Visionaries (Pure “Why” Triad)","axisSignature":"3 Why","websiteSummary":"The Apex Visionary pioneers a transformative possibility, establishes its intellectual credibility, and designs the long-range architecture required to sustain it. At their best, they create rigorous frameworks for a better future. Under stress, innovation becomes criticism, knowledge becomes superiority, and strategy treats people as elements in a system they were never invited to shape.","sigStrengthName":"Paradigm Architecture","sigStrengthDesc":"The Apex Visionary can integrate breakthrough insight, intellectual rigor, and long-range design into a comprehensive alternative.","sigParadox":"Designing a future for people without losing contact with the people who must inhabit it","devQuestion":"Can I invite people into the unfinished process rather than presenting a completed future they were never allowed to shape?","formationPractices":["Explain the vision without specialized language.","Invite a Servant, Host, Enthusiast, or Lover to critique the plan.","Test a small part of the model before expanding it.","Ask affected people to reshape the architecture.","Practice saying, “I may be wrong.”","Distinguish foundational principles from preferred designs.","Spend time with frontline practitioners.","Communicate uncertainty alongside conviction.","Measure human flourishing, not only conceptual coherence and strategic progress."],"leadershipStyleName":"The Paradigm Architect"},{"num":2,"name":"The Principled Reformer","slug":"principled-reformer","gifts":["catalyst","servant","erudite"],"pressure":{"name":"The Unpaid Reckoning","line":"Someone doing the work of reform, keeping private count of who else showed up, and finally going quiet with the receipts.","missing":{"gift":"enthusiast","text":"Encouragement is the missing brake. An Enthusiast keeps reform something people want to join rather than something they are being graded on — which is the difference between a movement and an indictment."},"pattern":"hardening","stages":[{"text":"The call for reform sharpens while the reformer quietly takes on more of the work and starts hedging every claim they cannot yet prove. The edge is visible. The load and the withheld judgment are not."},{"text":"The critique turns personal, the ledger of who actually helped starts running, and precision turns punitive. Others feel prosecuted, indebted and corrected at once, so they stop volunteering — which the reformer reads as proof of the original diagnosis."},{"text":"The work stops, the door closes, and the withdrawal itself becomes the final argument. They are left holding an accurate account of a broken thing and no relationship through which to fix it."}],"tell":"The sharpening is loud and the tallying is silent. Do not respond to the sharpening. Ask what they have been carrying that they have not mentioned."},"essence":"To challenge an inadequate system, establish the truth about what must change, and build a practical alternative whose integrity can be demonstrated through real work.","section":"Section 2: The Principled Architects (Vision & Action Hybrids)","axisSignature":"2 Why · 1 How","websiteSummary":"The Principled Reformer challenges an inadequate system, establishes the truth about what must change, and builds a practical alternative. At their best, they make reform credible through rigorous evidence and demonstrated work. Under stress, conviction becomes criticism, precision becomes contempt, and service becomes resentful martyrdom.","sigStrengthName":"Demonstrated Reform","sigStrengthDesc":"The Principled Reformer can connect moral or conceptual challenge with meticulous evidence and a working alternative.","sigParadox":"Refusing to compromise the principle without demanding perfection from every person","devQuestion":"Can I remain uncompromising about the essential principle while remaining patient with imperfect people and iterative progress?","formationPractices":["Define which principle is truly nonnegotiable.","Identify which standards are preferences.","Build a limited prototype before completing the entire case.","Ask frontline participants to critique the reform.","Delegate a meaningful portion of implementation.","State needs before resentment develops.","Celebrate progress publicly.","Practice correcting without contempt.","Rest before exhaustion becomes a moral identity."],"leadershipStyleName":"The Evidence-Based Reformer"},{"num":3,"name":"The Scholarly Investor","slug":"scholarly-investor","gifts":["catalyst","erudite","host"],"pressure":{"name":"The Closed Fund","line":"Conviction that hardened into criteria, and criteria that hardened into a closed hand.","missing":{"gift":"lover","text":"Mercy is the missing brake. A Lover keeps the person on the other side of the decision visible as a person, which is precisely what disappears when everything becomes criteria."},"pattern":"hardening","stages":[{"text":"Discernment turns toward disqualification, diligence acquires one more round, and the resources begin to be measured rather than moved. Each step is defensible on its own; together they mean nothing gets funded."},{"text":"Judgment about a proposal becomes judgment about the person making it, the bar moves whenever it is met, and what does get released carries conditions. People learn they are being assessed rather than backed."},{"text":"The fund closes, the reasoning walls off, and the conviction burns whatever bridges remain. The stewardship language that was true at the start is still in use at the end, when it has stopped being true."}],"tell":"Count decisions, not meetings. When the analysis is deepening and nothing has been released in a quarter, all three descents are running."},"essence":"To recognize transformative potential, investigate whether it is genuinely credible, and direct resources toward the ideas most capable of producing meaningful change.","section":"Section 2: The Principled Architects (Vision & Action Hybrids)","axisSignature":"2 Why · 1 How","websiteSummary":"The Scholarly Investor recognizes transformative possibilities, rigorously evaluates their credibility, and directs resources toward the ideas most likely to produce meaningful change. At their best, they unite courageous innovation with responsible stewardship. Under stress, analysis delays action, provision becomes control, and the desire to eliminate risk prevents worthy experiments from receiving a chance.","sigStrengthName":"Evidence-Informed Innovation Investment","sigStrengthDesc":"The Scholarly Investor can move meaningful resources behind an unconventional idea without abandoning discernment.","sigParadox":"Practicing due diligence without using analysis to eliminate every meaningful risk","devQuestion":"Can I distinguish responsible uncertainty from irresponsible risk and act before certainty is available?","formationPractices":["Create explicit investment criteria.","Set a deadline for due diligence.","Use staged investments to test uncertainty.","Include people affected by the innovation in evaluation.","Name risks openly rather than attempting to eliminate them.","Fund one credible initiative outside your familiar network.","Define decision rights before releasing resources.","Treat failed experiments as potential learning assets.","Give something meaningful without controlling the outcome."],"leadershipStyleName":"The Innovation Steward"},{"num":4,"name":"The Insightful Inspirer","slug":"insightful-inspirer","gifts":["catalyst","erudite","enthusiast"],"pressure":{"name":"The Brilliant Exit","line":"The insight gets sharper, the correction gets public, and then the room loses them entirely.","missing":{"gift":"servant","text":"Service is the missing brake. A Servant anchors the insight to work that has to be finished in place, and it is very hard to vanish from something you are still holding."},"pattern":"rotating","stages":[{"text":"The insight sharpens, the caveats multiply, and the delivery gets brighter to compensate for both. The room receives more energy and less substance, and cannot tell that anything is wrong."},{"text":"The accusation, the public correction and the charm now arrive together and contradict each other. People cannot tell whether they are being taught, indicted or entertained, so they stop bringing anything real."},{"text":"The bridges burn, the reasoning seals, and then the person is simply gone — usually with a story about outgrowing a place that was never going to understand. The story is convincing enough that even they believe it."}],"tell":"Rising energy alongside rising precision is the signature. When both climb at once, the exit is already being drafted."},"essence":"To discover a transformative insight, establish its credibility, and communicate it through a compelling narrative that awakens hope and participation.","section":"Section 3: The Visionary Mentors (Vision & Heart Hybrids)","axisSignature":"2 Why · 1 Who","websiteSummary":"The Insightful Inspirer discovers transformative insight, establishes its credibility, and communicates it through a narrative that awakens hope and participation. At their best, they make rigorous innovation accessible and compelling. Under stress, communication becomes performance, complexity is sacrificed for approval, and emotional impact is mistaken for lasting transformation.","sigStrengthName":"Compelling Translation","sigStrengthDesc":"The Insightful Inspirer can move an idea from specialist knowledge into public imagination.","sigParadox":"Making truth compelling without reshaping it to preserve applause","devQuestion":"Can I remain faithful to the truth when accuracy reduces immediate enthusiasm or approval?","formationPractices":["Separate facts, interpretations, and aspirations.","Ask a subject-matter expert to review the message.","Name one cost or limitation publicly.","Define the action the message is inviting.","Stay involved after the speaking moment.","Seek feedback from people who were not persuaded.","Practice communicating without dramatic language.","Resist using audience emotion as evidence of truth.","Build a team that can implement what you inspire."],"leadershipStyleName":"The Transformational Communicator"},{"num":5,"name":"The Compassionate Sage","slug":"compassionate-sage","gifts":["catalyst","erudite","lover"],"pressure":{"name":"The Wounded Authority","line":"Truth told with increasing precision by someone increasingly certain it will not be received.","missing":{"gift":"enthusiast","text":"Encouragement is the missing brake. An Enthusiast keeps the delivery warm enough to survive its own accuracy — this archetype's truth is usually correct and usually arrives at a temperature no one can receive."},"pattern":"rotating","stages":[{"text":"The truth-telling sharpens, the case gets qualified, and the room gets smoothed — often inside a single conversation. They say the hard thing, hedge it, then apologise for its temperature."},{"text":"The indictment and the plea arrive together: an accusation with an ache underneath it, followed by an airtight justification for both. The listener has no idea which one they are meant to answer."},{"text":"The fire, the wall and the silence combine into something that looks like disappearance and feels like grief. The truth was correct, the delivery was defended, and the person is no longer reachable."}],"tell":"Listen for the apology attached to the hard thing. When this archetype starts softening the truth immediately after saying it, the descent has begun."},"essence":"To recognize the truth that could unlock inner transformation, understand it deeply, and communicate it with enough compassion that it can be received without sacrificing either honesty or dignity.","section":"Section 3: The Visionary Mentors (Vision & Heart Hybrids)","axisSignature":"2 Why · 1 Who","websiteSummary":"The Compassionate Sage recognizes the truth that could unlock inner transformation, understands it deeply, and communicates it with compassion. At their best, they create enough safety for difficult truth to become a doorway to freedom. Under stress, insight becomes analysis, challenge becomes harshness, and compassion becomes silence or emotional absorption.","sigStrengthName":"Transformative Wisdom","sigStrengthDesc":"The Compassionate Sage can name difficult realities while helping people experience the truth as an invitation rather than a verdict.","sigParadox":"Creating enough safety for truth without making safety dependent upon avoiding truth","devQuestion":"Can I trust that honest, compassionate challenge may create temporary discomfort without destroying the relationship?","formationPractices":["Ask, “Would you like reflection, comfort, or challenge?”","Distinguish what you observed from what you inferred.","Offer interpretations with humility.","Say the essential truth in one sentence.","Allow silence after speaking.","Practice remaining connected when someone disagrees.","Establish boundaries around emotional responsibility.","Attend to personal wounds before interpreting others.","Repair delivery without abandoning the truth.","Ask whether the insight opens freedom or merely demonstrates perception."],"leadershipStyleName":"The Transformational Counselor"},{"num":6,"name":"The Visionary Implementer","slug":"visionary-implementer","gifts":["catalyst","servant","strategist"],"pressure":{"name":"The Solitary Build","line":"A better way, built at real personal cost, by someone who stopped asking for help and then stopped trusting it.","missing":{"gift":"lover","text":"Mercy is the missing brake. A Lover says the cost out loud while it is still a request rather than a grievance — this archetype's failure is almost always a conversation that happened eighteen months too late."},"pattern":"amplifying","stages":[{"text":"Urgency rises, the work quietly consolidates into one pair of hands, and the plan's grip tightens. Each of those looks like commitment. Together they mean nobody else can help."},{"text":"The accusation, the private ledger and the override run at once. Objections get steamrolled by someone who is also doing most of the labour, which makes the steamrolling nearly impossible to name."},{"text":"They burn the arrangement down, break under the load, and freeze out anyone who tries to intervene. The exhaustion is read as evidence of how much it mattered rather than of a broken system."}],"tell":"When the person doing the most work also stops asking for any, both outward descents are already at stage two."},"essence":"To innovate a better way, architect a workable path, and personally help turn the vision into reality.","section":"Section 2: The Principled Architects (Vision & Action Hybrids)","axisSignature":"2 Why · 1 How","websiteSummary":"The Visionary Implementer sees a better future, designs the system that can reach it, and does the practical work required to make it real. At their best, they create executable innovation. Under stress, they over-function, over-control, and carry work that should belong to others.","sigStrengthName":"Executable Innovation","sigStrengthDesc":"The Visionary Implementer can see something new without losing sight of what it will take to build it. They often become:","sigParadox":"Building the future without carrying the entire future alone","devQuestion":"Can I remain responsible for the vision without becoming responsible for every task?","formationPractices":["Delegate an outcome, not merely a task.","Ask, “Does this need to be redesigned, or merely completed?”","Limit active innovations to a sustainable number.","Invite affected people into the design process.","Practice receiving help without correcting how it is offered.","Celebrate shared ownership more than personal productivity."],"leadershipStyleName":"The Builder of New Systems"},{"num":7,"name":"The Resourced Revolutionary","slug":"resourced-revolutionary","gifts":["catalyst","host","strategist"],"pressure":{"name":"The Funded Ultimatum","line":"A cause genuinely worth backing, backed with strings, run by someone who has stopped consulting anyone.","missing":{"gift":"servant","text":"Service is the missing brake. A Servant keeps the work in contact with what it actually costs the people doing it — which is the information this archetype systematically stops receiving."},"pattern":"amplifying","stages":[{"text":"The cause becomes non-negotiable, the funding starts being measured, and the decisions consolidate. A movement that was gathering people begins, very quietly, to become an administration."},{"text":"Conviction, conditional money and unilateral authority combine into something close to coercion — sincerely meant. Nobody downstream can separate the mission's demands from this person's preferences, because they have merged."},{"text":"The bridges burn, the hand closes, and the leadership goes cold. The revolution ends up organised exactly like the institution it was built to replace, run by someone who cannot see the resemblance."}],"tell":"Watch for the first condition attached to money that used to be given freely. That is the earliest catchable moment."},"essence":"To pioneer transformative possibilities, gather the resources they require, and build structures capable of sustaining them.","section":"Section 2: The Principled Architects (Vision & Action Hybrids)","axisSignature":"2 Why · 1 How","websiteSummary":"The Resourced Revolutionary pioneers transformative possibilities, gathers what they need, and builds structures capable of carrying them into the future. At their best, they turn resources into enduring service. Under stress, stewardship can become control and mission can become empire.","sigStrengthName":"Sustainable Transformation","sigStrengthDesc":"","sigParadox":"Stewarding power without being possessed by it","devQuestion":"Do I possess these resources for the mission, or has the mission become a justification for possessing them?","formationPractices":["Establish independent accountability over money and authority.","Give anonymously when possible.","Ask who gains agency through each investment.","Include human flourishing among success metrics.","Invite critique from people who do not depend upon your approval.","Periodically identify what should be released rather than expanded."],"leadershipStyleName":"The Institution-Building Steward"},{"num":8,"name":"The Galvanizing Leader","slug":"galvanizing-leader","gifts":["catalyst","enthusiast","strategist"],"pressure":{"name":"The Managed Movement","line":"A true call, smoothed for the crowd, then executed alone when the crowd does not hold.","missing":{"gift":"erudite","text":"Teaching is the missing brake. An Erudite insists the message stay accurate under compression — this archetype's real risk is that the version everyone repeats is not quite the version that was true."},"pattern":"amplifying","stages":[{"text":"The call sharpens, the delivery brightens, and the plan tightens. The room feels more inspired and has less room to move — a combination that produces enthusiastic compliance rather than genuine buy-in."},{"text":"Moral pressure, managed messaging and overridden dissent operate together. Anyone raising a hard question meets conviction, then warmth, then a decision that had already been taken."},{"text":"The movement is scorched, the leader disappears from the relationships that built it, and what remains is run coldly by one person. Everyone remembers the speeches and nobody remembers being asked."}],"tell":"When the message gets more compelling at the same rate it gets less specific, all three descents are underway."},"essence":"To innovate a better future, inspire people to believe in it, and organize collective action that makes it possible.","section":"Section 3: The Visionary Mentors (Vision & Heart Hybrids)","axisSignature":"2 Why · 1 Who","websiteSummary":"The Galvanizing Leader sees a better future, helps people believe in it, and organizes collective movement toward it. At their best, they awaken courageous participation. Under stress, inspiration becomes urgency, strategy becomes pressure, and belonging can become conditional upon agreement.","sigStrengthName":"Mobilized Possibility","sigStrengthDesc":"","sigParadox":"Mobilizing people without pressuring them","devQuestion":"Am I inviting willing participation, or using hope, urgency, and belonging to produce compliance?","formationPractices":["Invite someone to identify the weaknesses in your vision.","Create legitimate pathways for disagreement.","Communicate costs as clearly as benefits.","Practice presence without recruitment.","Celebrate faithful limits, not only extraordinary commitment.","Ask whether people are becoming more free through your leadership.","Allow seasons of consolidation rather than creating continuous urgency."],"leadershipStyleName":"The Mobilizing Visionary"},{"num":9,"name":"The Protective Visionary","slug":"protective-visionary","gifts":["catalyst","strategist","lover"],"pressure":{"name":"The Guarded Mandate","line":"Protecting people by deciding for them, until the protector is the loneliest person in the room.","missing":{"gift":"erudite","text":"Teaching is the missing brake. An Erudite slows the certainty enough to ask whether the threat is still what it was — this archetype often keeps defending against a danger that passed some time ago."},"pattern":"amplifying","stages":[{"text":"The threat sharpens, the grip tightens, and the person absorbs the resulting tension rather than naming it. Protection is being built, and its cost is being hidden by the same person building it."},{"text":"They indict the danger, override the people they are protecting, then plead for understanding about having done so. The protected experience being decided for and then asked to be grateful."},{"text":"The scorching, the freezing and the shutting down arrive close together, and the guardian ends up the most isolated person inside the arrangement they built for everyone else's safety."}],"tell":"The plea is the tell. When protective decisions start arriving with an account of how hard they were to make, stage two is here."},"essence":"To pioneer necessary transformation, lead it decisively, and protect the dignity and well-being of the people affected by it.","section":"Section 3: The Visionary Mentors (Vision & Heart Hybrids)","axisSignature":"2 Why · 1 Who","websiteSummary":"The Protective Visionary pioneers necessary change while guarding the dignity of those affected by it. At their best, they unite courage, strategic direction, and humane care. Under stress, compassion becomes over-responsibility and protection becomes control.","sigStrengthName":"Humane Transformation","sigStrengthDesc":"","sigParadox":"Protecting people without protecting them from every necessary difficulty","devQuestion":"Am I protecting dignity, or preventing people from experiencing the difficulty required for development?","formationPractices":["Ask before rescuing.","Define what belongs to your responsibility and what does not.","Build support structures rather than becoming the support structure.","Allow honest lament without immediately fixing it.","Invite vulnerable people into decision-making.","Practice boundaries as a form of sustainable love.","Measure whether care is increasing another person’s agency."],"leadershipStyleName":"The Transformational Protector"},{"num":10,"name":"The Master Craftsman","slug":"master-craftsman","gifts":["servant","erudite","strategist"],"pressure":{"name":"The Standard No One Meets","line":"Excellent work absorbed without complaint, then defended as a standard, then kept from everyone.","missing":{"gift":"enthusiast","text":"Encouragement is the missing brake. An Enthusiast makes a standard something people aspire to rather than something they fail — the same bar, received completely differently."},"pattern":"hardening","stages":[{"text":"The work quietly expands, the standards acquire caveats, and delegation stops. Nothing looks wrong — the output is excellent — so the load, the withheld judgment and the control all stay invisible."},{"text":"The silent tally, the punitive correction and the override combine into a workplace where nobody's work is good enough and nobody is told why in time to fix it."},{"text":"The collapse, the wall and the freeze happen together, and the knowledge goes with them. What is lost is not only a person but everything only that person knew how to do."}],"tell":"Ask who else could do this if they were away for a month. The answer is the diagnostic."},"essence":"To master what is true, design what will work, and execute it with disciplined excellence.","section":"Section 2: The Principled Architects (Vision & Action Hybrids)","axisSignature":"2 Why · 1 How","websiteSummary":"The Master Craftsman understands deeply, designs intelligently, and builds with disciplined excellence. At their best, they transform knowledge into dependable systems and skilled work. Under stress, excellence becomes perfectionism, expertise becomes superiority, and others are denied room to learn.","sigStrengthName":"Integrated Mastery","sigStrengthDesc":"","sigParadox":"Pursuing excellence without making perfection the price of participation","devQuestion":"Can I preserve excellence while allowing apprenticeship, experimentation, and human limitation?","formationPractices":["Define the purpose before establishing the standard.","Teach one person to perform a task you usually retain.","Submit unfinished work for feedback.","Identify where excellence matters most—and where adequacy is sufficient.","Celebrate another person’s progress before correcting remaining flaws.","Practice learning publicly.","Complete selected projects without one final round of refinement."],"leadershipStyleName":"The Architect of Excellence"},{"num":11,"name":"The Prudent Architect","slug":"prudent-architect","gifts":["erudite","host","strategist"],"pressure":{"name":"The Conditional Plan","line":"A decision deferred, then priced, then made unilaterally when the deferral finally ran out.","missing":{"gift":"catalyst","text":"Prophecy is the missing brake. A Catalyst names the thing everyone is avoiding while there is still time to change course — this archetype's deferrals are usually protecting one unspoken disagreement."},"pattern":"hardening","stages":[{"text":"The recommendation acquires conditions, the resources acquire conditions, and the plan tightens around the resulting uncertainty. Three different forms of not-quite-committing, running at once."},{"text":"Correction, leverage and override replace consultation. The decision gets made by whichever of the three moves first, and the reasoning behind it is never made available to anyone."},{"text":"The reasoning seals, the hand closes, and the leadership goes cold. An architecture built to last outlives the trust of everyone who was supposed to live inside it."}],"tell":"Count the decisions waiting on one more piece of information. When that number stops falling, the descent has started."},"essence":"To build enduring, well-resourced institutions upon sound knowledge, wise stewardship, and long-range strategic design.","section":"Section 2: The Principled Architects (Vision & Action Hybrids)","axisSignature":"2 Why · 1 How","websiteSummary":"The Prudent Architect combines deep research, wise provision, and long-range strategy to build institutions that endure. At their best, prudence enables faithful action. Under stress, caution becomes control and the institution’s machinery eclipses the people it exists to serve.","sigStrengthName":"Durable Stewardship","sigStrengthDesc":"The Prudent Architect can create institutions that remain stable through changing leadership, economic pressures, and cultural transitions.","sigParadox":"Preserving the mission without preserving the machinery","devQuestion":"Can I preserve what is essential while allowing structures that once served the mission to change or end?","formationPractices":["Establish a deadline before beginning research.","Fund a worthy initiative that includes manageable uncertainty.","Review which policies no longer serve the mission.","Include qualitative human outcomes alongside financial metrics.","Practice generosity without controlling every detail.","Create a process for retiring obsolete systems.","Invite challenge from someone outside the institutional culture."],"leadershipStyleName":"The Institutional Steward"},{"num":12,"name":"The Engaging Mentor","slug":"engaging-mentor","gifts":["erudite","enthusiast","strategist"],"pressure":{"name":"The Curriculum Without a Student","line":"Depth withheld until it is ready, packaged when it is not, then delivered to no one in particular.","missing":{"gift":"lover","text":"Mercy is the missing brake. A Lover notices which particular student stopped being reached — a signal that vanishes entirely once mentoring becomes a curriculum."},"pattern":"rotating","stages":[{"text":"The material is never quite ready, the delivery gets more energetic to cover the gap, and the mentoring tightens into a program. Depth withheld, warmth increased, structure imposed."},{"text":"Public correction, spun reassurance and overridden objection produce a mentee who cannot tell whether they are doing well. They are praised, corrected and redirected in the same conversation."},{"text":"The teacher seals, the warmth vanishes, and the system runs on without either. What remains is a curriculum administered by someone who has stopped noticing who is in the room."}],"tell":"When the encouragement stops being specific to the person receiving it, all three have started."},"essence":"To awaken growth by combining credible knowledge, relational encouragement, and a clear developmental path.","section":"Section 3: The Visionary Mentors (Vision & Heart Hybrids)","axisSignature":"2 Why · 1 Who","websiteSummary":"The Engaging Mentor combines deep understanding, inspiring connection, and strategic guidance to help people grow. At their best, they make development clear, hopeful, and personally owned. Under stress, mentoring becomes management and people begin to feel like projects.","sigStrengthName":"Activated Development","sigStrengthDesc":"","sigParadox":"Guiding growth without scripting another person’s life","devQuestion":"Can I champion another person’s growth without needing to author it?","formationPractices":["Ask, “Do you want listening, advice, or coaching?”","Spend an entire conversation asking questions without teaching.","Let the learner define the desired outcome.","Name potential without prescribing identity.","Bless a person’s path when it differs from your recommendation.","Measure mentoring success by growing autonomy.","Invest in one slow, unglamorous developmental relationship."],"leadershipStyleName":"The Developmental Guide"},{"num":13,"name":"The Wise Shepherd","slug":"wise-shepherd","gifts":["erudite","strategist","lover"],"pressure":{"name":"The Silent Rod","line":"Counsel held back, then a decision made over the top of it, then a shepherd who has gone quiet.","missing":{"gift":"catalyst","text":"Prophecy is the missing brake. A Catalyst makes the unspoken thing speakable before it calcifies — this archetype's crises are almost always things that were known and unsaid for a long time."},"pattern":"rotating","stages":[{"text":"The counsel is withheld pending certainty, the grip tightens, and the discomfort is absorbed instead of named. The flock meets a shepherd who is present, quieter, and less consultative."},{"text":"Correction, override and plea run together: a decision made for their good, defended with reasoning, and accompanied by hurt that it was not received well."},{"text":"The wall, the freeze and the silence combine. The shepherd is still there, still responsible, and no longer reachable by anyone — including the people who need them most."}],"tell":"Watch for counsel that arrives after the decision rather than before it. That inversion is the earliest sign."},"essence":"To guide people with sound wisdom, compassionate presence, and a clear path toward wholeness and purposeful action.","section":"Section 3: The Visionary Mentors (Vision & Heart Hybrids)","axisSignature":"2 Why · 1 Who","websiteSummary":"The Wise Shepherd combines deep understanding, strategic direction, and compassionate presence. At their best, they help people feel safe enough to move toward wholeness. Under stress, care becomes over-responsibility, analysis delays action, and guidance becomes quietly controlling.","sigStrengthName":"Compassionate Discernment","sigStrengthDesc":"","sigParadox":"Caring deeply without carrying people indefinitely","devQuestion":"Can I offer wise and compassionate guidance without taking ownership of another person’s choices?","formationPractices":["Make a compassionate decision before universal agreement is available.","State expectations without excessive explanation.","Ask whether a person needs empathy, guidance, or accountability.","Practice allowing disappointment without repairing it prematurely.","Establish limits around emotional availability.","Build support networks rather than becoming the sole support.","Notice when analysis is replacing emotional presence."],"leadershipStyleName":"The Pastoral Strategist"},{"num":14,"name":"The Practical Revolutionary","slug":"practical-revolutionary","gifts":["catalyst","servant","host"],"pressure":{"name":"The Withdrawn Alternative","line":"A tangible answer to what is broken, built alone, funded alone, and eventually taken back.","missing":{"gift":"enthusiast","text":"Encouragement is the missing brake. An Enthusiast keeps people wanting to be part of the thing — without which the alternative has exactly one owner and therefore exactly one point of failure."},"pattern":"hardening","stages":[{"text":"The critique sharpens while the build quietly consolidates into one person's hands and the resources start being measured. Labour and money begin flowing from the same source, unasked."},{"text":"Indictment, silent tally and conditional provision combine into an alternative that only one person can fund, only one person can build, and everyone else is somehow failing to deserve."},{"text":"The burn, the collapse and the closed hand arrive together, and the alternative disappears with the person carrying it — leaving the broken thing it was replacing still standing."}],"tell":"When one person is supplying both the labour and the money and has stopped asking for either, it has begun."},"essence":"To pioneer a tangible alternative to what is broken by combining bold innovation, hands-on service, and generous provision.","section":"Section 4: The Bedrock Builders (Action-Dominant Triads)","axisSignature":"1 Why · 2 How","websiteSummary":"The Practical Revolutionary challenges inadequate systems by building and resourcing a tangible alternative. At their best, they turn innovation into practical hope. Under stress, courage becomes criticism, service becomes martyrdom, and generosity becomes control.","sigStrengthName":"Embodied Innovation","sigStrengthDesc":"","sigParadox":"Building a better future without becoming its exhausted martyr","devQuestion":"Can I remain deeply committed without proving the vision through self-exhaustion?","formationPractices":["Require at least one co-owner before launching something new.","Set a time, resource, and energy limit for the prototype.","Ask the people affected what they actually need.","Receive help without redoing it.","Practice anonymous generosity.","Build rest into the operating model.","Review whether innovation is increasing community capacity or founder dependence."],"leadershipStyleName":"The Hands-On Innovator"},{"num":15,"name":"The Faithful Steward","slug":"faithful-steward","gifts":["servant","erudite","host"],"pressure":{"name":"The Audited Gift","line":"Quiet faithfulness that becomes quiet accounting, and finally a closed hand with excellent records.","missing":{"gift":"enthusiast","text":"Encouragement is the missing brake. An Enthusiast keeps gratitude circulating rather than accumulating — this archetype's collapse is almost always a decade of unacknowledged reliability."},"pattern":"sealing","stages":[{"text":"Work accumulates, judgment is withheld, and generosity begins to be measured. All three are silent. This is the most invisible strain in the system: there is genuinely nothing to see."},{"text":"The ledger runs, the corrections sharpen, and the giving acquires terms. Still almost nothing surfaces, because none of these three gifts has any native mechanism for confrontation."},{"text":"The collapse, the wall and the closed hand happen at once, and every route to this person closes in the same week — practical, intellectual and material. Nobody sees it coming, including them."}],"tell":"This one cannot be caught by watching. It can only be caught by asking, on a schedule, when nothing appears wrong."},"essence":"To care for entrusted people, responsibilities, and resources with knowledgeable diligence, practical wisdom, and trustworthy generosity.","section":"Section 4: The Bedrock Builders (Action-Dominant Triads)","axisSignature":"1 Why · 2 How","websiteSummary":"The Faithful Steward combines careful understanding, diligent work, and responsible generosity. At their best, they make entrusted resources more fruitful. Under stress, diligence becomes over-functioning, accuracy becomes criticism, and stewardship becomes gatekeeping.","sigStrengthName":"Trustworthy Provision","sigStrengthDesc":"","sigParadox":"Protecting what is entrusted without gripping it too tightly","devQuestion":"Can I care responsibly for what is entrusted while remembering that it was entrusted for a purpose?","formationPractices":["Give something meaningful without controlling how it is used.","Teach another person a responsibility you usually retain.","Publish clear standards rather than enforcing private expectations.","Differentiate essential accountability from personal preference.","Allow one recoverable mistake without taking the responsibility back.","Ask for appreciation directly rather than serving resentfully.","Review whether accumulated resources are fulfilling their intended purpose."],"leadershipStyleName":"The Trustworthy Custodian"},{"num":16,"name":"The Joyful Benefactor","slug":"joyful-benefactor","gifts":["servant","enthusiast","host"],"pressure":{"name":"The Cheerful Depletion","line":"Giving past capacity with a smile on it, deflecting every offer of help, and then quietly shutting the door.","missing":{"gift":"strategist","text":"Leadership is the missing brake. A Strategist sets the limit before the limit sets itself — this archetype has no native mechanism for a planned stop, only for an unplanned one."},"pattern":"silent-drift","stages":[{"text":"The load grows, the brightness grows with it, and the generosity starts being quietly rationed. The performance is convincing precisely because the warmth behind it is real."},{"text":"The tally, the spin and the leverage run together. Offers of help get deflected with a joke, the giving develops strings nobody can name, and the cost stays invisible for another year."},{"text":"The collapse, the vanishing and the closed hand arrive at once. To everyone else this is sudden. To them it has been coming for a decade."}],"tell":"Notice when a specific offer of help gets a cheerful non-answer. That deflection is the whole descent in miniature."},"essence":"To create generous communities of belonging through practical service, contagious joy, and abundant hospitality.","section":"Section 4: The Bedrock Builders (Action-Dominant Triads)","axisSignature":"2 How · 1 Who","websiteSummary":"The Joyful Benefactor combines practical service, generous provision, and contagious warmth to create communities of belonging. At their best, they make people feel genuinely welcomed and celebrated. Under stress, hospitality becomes performance, service becomes exhaustion, and giving begins to carry hidden expectations.","sigStrengthName":"Celebratory Hospitality","sigStrengthDesc":"","sigParadox":"Creating belonging without performing for belonging","devQuestion":"Can I believe that I belong even when I am not the person making belonging possible for everyone else?","formationPractices":["Attend an event without helping organize it.","Ask directly for assistance.","Establish a hospitality budget before making plans.","Create one intentionally simple gathering.","Allow someone else to host in a different style.","Welcome people who cannot reciprocate.","Notice when celebration is being used to avoid grief or conflict."],"leadershipStyleName":"The Community Host"},{"num":17,"name":"The Master Provider","slug":"master-provider","gifts":["servant","host","strategist"],"pressure":{"name":"The Provisioned Silence","line":"Everything supplied, conditions attached, and no one left who is able to say no.","missing":{"gift":"lover","text":"Mercy is the missing brake. A Lover keeps provision an act of care rather than a term of trade — and can tell the difference from the inside, which this archetype cannot."},"pattern":"hardening","stages":[{"text":"Needs get met before they are voiced, provision starts being measured, and the decisions consolidate. The household or team reorganises around a level of support nobody asked for and nobody can now question."},{"text":"The silent ledger, the conditional provision and the override combine into an arrangement where disagreeing with the provider is indistinguishable from ingratitude."},{"text":"The collapse, the closed hand and the freeze land together, and everyone downstream discovers at once how much was being carried and how little of it was ever discussable."}],"tell":"Ask whether anyone in this system has said no to them in the past year and had it stick."},"essence":"To build reliable systems that anticipate, organize, and provide for a community’s practical needs over time.","section":"Section 4: The Bedrock Builders (Action-Dominant Triads)","axisSignature":"1 Why · 2 How","websiteSummary":"The Master Provider builds and maintains the systems that keep communities supplied, organized, and functioning. At their best, they create dependable provision that outlasts them. Under stress, competence becomes control and the system becomes dependent upon their exhaustion.","sigStrengthName":"Sustainable Provision","sigStrengthDesc":"","sigParadox":"Becoming essential without becoming indispensable","devQuestion":"Can I build a system people can depend upon without building a system that depends entirely upon me?","formationPractices":["Take a planned absence and observe what breaks.","Document one critical process each week.","Assign both responsibility and decision-making authority.","Ask whether each control addresses an actual risk.","Let another person solve a problem differently.","Build succession into every major role.","Measure the operation’s resilience without your intervention."],"leadershipStyleName":"The Operational Architect"},{"num":18,"name":"The Tender Provider","slug":"tender-provider","gifts":["servant","host","lover"],"pressure":{"name":"The Quiet Cost","line":"Care given until it hurts, then care given with a hook in it, and then nothing at all.","missing":{"gift":"catalyst","text":"Prophecy is the missing brake. A Catalyst makes the unspoken resentment sayable while it is still small — this archetype's entire failure mode is a true thing that was never once said out loud."},"pattern":"silent-drift","stages":[{"text":"The care expands, the resources start being counted, and the tension is absorbed rather than named. Nothing points outward; the entire strain is being paid privately."},{"text":"The tally, the leverage and the plea braid together into care that has a hook in it and a hurt underneath it, neither of which is ever stated plainly."},{"text":"The collapse, the closed hand and the silence arrive together. The most consistently generous person in the system stops completely, and cannot explain why in terms anyone finds proportionate."}],"tell":"There is no visible tell. Ask what it cost them, specifically, and do not accept the first cheerful answer."},"essence":"To translate compassion into tangible care through attentive service, generous provision, and emotionally present love.","section":"Section 4: The Bedrock Builders (Action-Dominant Triads)","axisSignature":"2 How · 1 Who","websiteSummary":"The Tender Provider turns empathy into practical, generous care. At their best, they help people feel emotionally seen and tangibly supported. Under stress, compassion becomes over-responsibility, generosity creates dependence, and the caregiver disappears beneath the needs of others.","sigStrengthName":"Embodied Compassion","sigStrengthDesc":"","sigParadox":"Meeting needs without making need the basis of relationship","devQuestion":"Can I help another person become strong enough to need less from me?","formationPractices":["Ask before helping.","Define the scope and duration of assistance.","Build a team around recurring needs.","Practice receiving without immediate reciprocation.","Leave one nonessential need for another person to meet.","Track personal emotional and physical capacity.","Ask whether the care increases dignity and agency."],"leadershipStyleName":"The Compassionate Provider"},{"num":19,"name":"The Compassionate Agitator","slug":"compassionate-agitator","gifts":["catalyst","enthusiast","lover"],"pressure":{"name":"The Burned Advocate","line":"A voice raised for people who are hurting, softened to keep the room, and then extinguished.","missing":{"gift":"strategist","text":"Leadership is the missing brake. A Strategist converts outrage into something with a sequence and a stopping point — without it, this archetype's compassion has no container and burns at full rate until it is gone."},"pattern":"oscillating","stages":[{"text":"The advocacy sharpens, the delivery brightens to keep the relationships alive, and the private cost is absorbed. Confrontation and warmth begin alternating, sometimes inside one conversation."},{"text":"Indictment, spin and plea cycle unpredictably. People close to them get confrontation, then charm, then hurt, and cannot find a stable version of the person to respond to."},{"text":"The scorch, the vanishing and the silence combine into a burnout that looks from outside like sudden indifference and is actually someone who ran at full rate until there was nothing left."}],"tell":"The oscillation itself is the tell. When confrontation and charm start alternating faster, the cycle is tightening."},"essence":"To awaken people to suffering, imagine a more humane possibility, and rally a community toward courageous, compassionate transformation.","section":"Section 5: The Heart-Centered Connectors (Connection-Dominant Triads)","axisSignature":"1 Why · 2 Who","websiteSummary":"The Compassionate Agitator feels the human cost of what is broken, challenges the assumptions sustaining it, and rallies people toward a more humane possibility. At their best, they transform compassion into moral imagination and constructive change. Under stress, challenge becomes condemnation, urgency becomes emotional pressure, and belonging becomes conditional upon agreement.","sigStrengthName":"Mobilized Compassion","sigStrengthDesc":"","sigParadox":"Awakening conscience without weaponizing shame","devQuestion":"Can I confront complicity while continuing to believe in people’s capacity to change?","formationPractices":["State the desired alternative before issuing the critique.","Ask affected people how they want their stories represented.","Practice one-on-one dialogue with a hesitant potential ally.","Distinguish urgency from emotional escalation.","Create spaces where honest questions do not threaten belonging.","Limit advocacy exposure when the nervous system is overwhelmed.","Identify one practical experiment that embodies the desired future.","Pray for or humanize someone positioned as an opponent."],"leadershipStyleName":"The Humane Change-Maker"},{"num":20,"name":"The Devoted Caretaker","slug":"devoted-caretaker","gifts":["servant","enthusiast","lover"],"pressure":{"name":"The Invisible Ledger","line":"Endless care, unfailing brightness, and a silence at the end that no one saw coming.","missing":{"gift":"catalyst","text":"Prophecy is the missing brake. A Catalyst says the true thing out loud years earlier — this archetype has no gift that generates confrontation, which is precisely why the ledger stays invisible until it closes."},"pattern":"vanishing","stages":[{"text":"The care expands, the brightness holds, and the tension is absorbed. Three gifts, none of which point outward, all straining — which is exactly why nobody notices anything."},{"text":"The tally runs, the mood stays light, and the hurt leaks sideways. The people benefiting most receive warmth, a faint sense that something is off, and no way to locate it."},{"text":"The collapse, the vanishing and the silence happen together. The person who held everything is gone, and the household or team discovers all at once how much of it was them."}],"tell":"This archetype has no gift that generates confrontation. Nothing will surface on its own; the check has to be structural and scheduled."},"essence":"To surround people with holistic care through practical help, uplifting encouragement, and deeply empathetic presence.","section":"Section 5: The Heart-Centered Connectors (Connection-Dominant Triads)","axisSignature":"1 How · 2 Who","websiteSummary":"The Devoted Caretaker combines empathy, encouragement, and practical service to offer whole-person care. At their best, people feel deeply seen, strengthened, and supported. Under stress, caregiving becomes identity, encouragement avoids pain, and service becomes a way to secure love.","sigStrengthName":"Whole-Person Care","sigStrengthDesc":"","sigParadox":"Loving through service without making service the price of being loved","devQuestion":"Can I receive love when I have done nothing to earn it and cannot make anyone feel better?","formationPractices":["Wait to be asked before solving a nonurgent problem.","Ask, “Would you like empathy, encouragement, or practical help?”","Receive one act of care without immediately reciprocating.","State a personal need directly.","Establish clear limits around availability.","Let someone remain disappointed without abandoning the boundary.","Practice sitting with pain without trying to brighten it.","Develop relationships not organized around caregiving."],"leadershipStyleName":"The Nurturing Supporter"},{"num":21,"name":"The Affectionate Counselor","slug":"affectionate-counselor","gifts":["erudite","enthusiast","lover"],"pressure":{"name":"The Withheld Word","line":"The counsel that was never quite ready, the reassurance offered instead, and the counselor who went quiet.","missing":{"gift":"strategist","text":"Leadership is the missing brake. A Strategist forces the decision the caring keeps deferring — this archetype knows the answer far earlier than it says it."},"pattern":"vanishing","stages":[{"text":"The hard word is withheld, the warmth increases to fill its place, and the discomfort is absorbed. The counselee leaves feeling better and no wiser, and the counselor knows it."},{"text":"Correction, spin and plea combine into counsel that arrives late, wrapped and hedged, followed by hurt when it is not acted on. Nobody involved can tell what was actually advised."},{"text":"The seal, the vanishing and the silence land together, and the person most trusted with everyone's inner life becomes unreachable without ever having said a difficult sentence."}],"tell":"Watch for encouragement offered where an assessment was requested. That substitution is stage one."},"essence":"To create a safe and hopeful relationship in which emotional experience is deeply understood, wise insight becomes accessible, and people discover their own path toward growth.","section":"Section 5: The Heart-Centered Connectors (Connection-Dominant Triads)","axisSignature":"1 Why · 2 Who","websiteSummary":"The Affectionate Counselor combines emotional attunement, wise understanding, and hopeful encouragement. At their best, people feel deeply seen and gently strengthened. Under stress, empathy becomes absorption, insight becomes over-analysis, and helping becomes a way to secure relational significance.","sigStrengthName":"Hopeful Insight","sigStrengthDesc":"","sigParadox":"Understanding another person without absorbing or defining them","devQuestion":"Can I offer understanding without turning another person into my interpretation of them?","formationPractices":["Ask permission before offering an interpretation.","Use phrases such as, “I wonder whether…” rather than, “What is happening is…”","Spend a conversation offering presence without advice.","Establish a ritual for releasing emotional burdens after care conversations.","Allow another person to reject your interpretation.","Receive support without becoming the counselor.","Notice when encouragement is moving too quickly past grief.","Cultivate relationships based on mutuality rather than helping."],"leadershipStyleName":"The Relational Interpreter"},{"num":22,"name":"The Lavish Celebrant","slug":"lavish-celebrant","gifts":["enthusiast","host","lover"],"pressure":{"name":"The Empty Table","line":"A feast thrown for everyone, subtly invoiced, by a host nobody thought to ask about.","missing":{"gift":"erudite","text":"Teaching is the missing brake. An Erudite asks the honest question underneath the celebration — the one question this archetype's warmth is very good at preventing anyone from asking."},"pattern":"vanishing","stages":[{"text":"The gatherings get bigger, the giving starts being counted, and the host absorbs whatever tension the room produces. The generosity is real and the arithmetic underneath it has already started."},{"text":"The spin, the leverage and the plea run together. Hospitality acquires an unstated invoice and a faint undertow of hurt, and guests feel both without being able to name either."},{"text":"The vanishing, the closed hand and the silence arrive at once. The person who filled every room they entered concludes that no one was ever coming for them, and stops opening the door."}],"tell":"Notice who asks this person how they are and does not accept 'wonderful.' If nobody does, the descent has no brake at all."},"essence":"To create beautiful, generous experiences in which people feel cherished, connected, and joyfully welcomed into belonging.","section":"Section 5: The Heart-Centered Connectors (Connection-Dominant Triads)","axisSignature":"1 How · 2 Who","websiteSummary":"The Lavish Celebrant creates beautiful, generous experiences in which people feel cherished and connected. At their best, celebration makes belonging tangible. Under stress, hospitality becomes performance, generosity seeks emotional repayment, and joy leaves little room for grief or difference.","sigStrengthName":"Embodied Belonging","sigStrengthDesc":"","sigParadox":"Creating joy for others without needing their joy to validate you","devQuestion":"Can I offer celebration freely without needing the room’s delight to prove my worth or the event’s success?","formationPractices":["Host a simple gathering with minimal production.","Set the budget before imagining the experience.","Allow another person to shape the event.","Welcome someone who cannot reciprocate socially or materially.","Create room for lament within communal celebration.","Participate as a guest in something you did not create.","Receive criticism without immediately repairing the experience.","Practice being present after the event’s activity ends."],"leadershipStyleName":"The Curator of Belonging"},{"num":23,"name":"The Encouraging Shepherd","slug":"encouraging-shepherd","gifts":["enthusiast","strategist","lover"],"pressure":{"name":"The Hollow Rally","line":"Encouragement turned up, dissent rolled over, and a shepherd who no longer believes their own speech.","missing":{"gift":"erudite","text":"Teaching is the missing brake. An Erudite checks whether the encouragement is still true — this archetype can sustain a message long past the point where it stopped being accurate."},"pattern":"oscillating","stages":[{"text":"The encouragement intensifies, the plan tightens, and the doubt is absorbed rather than voiced. Morale becomes the metric while the gap between what is said and what is true begins to widen."},{"text":"Spin, override and plea alternate. The person raising a hard question is encouraged, then handled, then made to feel they have wounded someone — often in that order and in one meeting."},{"text":"The vanishing, the freeze and the silence combine. The shepherd who asked everyone to believe has stopped believing, and leaves a community that never once heard them say so."}],"tell":"When the encouragement stops matching what people can see with their own eyes, stage one is over."},"essence":"To guide people toward a shared purpose by creating a culture of encouragement, emotional safety, and clear developmental direction.","section":"Section 5: The Heart-Centered Connectors (Connection-Dominant Triads)","axisSignature":"1 Why · 2 Who","websiteSummary":"The Encouraging Shepherd leads people toward shared purpose through hope, emotional safety, and clear direction. At their best, belonging and accountability strengthen one another. Under stress, encouragement replaces correction, care becomes over-accommodation, and direction becomes indirect control.","sigStrengthName":"Safe Mobilization","sigStrengthDesc":"The Encouraging Shepherd can create cultures in which people feel secure enough to take risks, receive guidance, and contribute meaningfully.","sigParadox":"Creating safety without protecting people from accountability","devQuestion":"Can I preserve belonging while clearly naming what growth, responsibility, and repair require?","formationPractices":["Pair every affirmation with one clear developmental invitation.","Address concerns before frustration accumulates.","State expectations behaviorally rather than emotionally.","Allow someone to be disappointed without withdrawing care.","Distinguish relational safety from emotional comfort.","Stop compensating privately for another person’s unaddressed responsibility.","Ask team members what remains difficult to say.","Establish transparent consequences and pathways for repair."],"leadershipStyleName":"The People-Centered Guide"},{"num":24,"name":"The Practical Pioneer","slug":"practical-pioneer","gifts":["catalyst","servant","enthusiast"],"pressure":{"name":"The Abandoned Prototype","line":"A new thing built by hand, resented in private, and walked away from without warning.","missing":{"gift":"strategist","text":"Leadership is the missing brake. A Strategist gives the work a horizon long enough to survive its hard middle — this archetype builds beautifully and has no native mechanism for finishing."},"pattern":"rotating","stages":[{"text":"Urgency sharpens, the build consolidates into one pair of hands, and the energy stays high. The prototype gets made, and the imbalance underneath it is invisible behind the enthusiasm."},{"text":"Indictment, private tally and spin cycle unpredictably. The same person confronts, resents and reassures within a day, and colleagues cannot work out which one is the real position."},{"text":"The burn, the collapse and the disappearance arrive together. Something genuinely new is abandoned at exactly the point where it needed a boring middle, and the exit is framed as needing a new challenge."}],"tell":"When the person doing the hands-on work starts talking about what is next, the third descent has already begun."},"essence":"To pioneer a new possibility, build its first tangible expression, and inspire others to participate in making it real.","section":"Section 6: The Groundbreakers (Balanced Triads · Catalyst-Led)","axisSignature":"1 Why · 1 How · 1 Who","websiteSummary":"The Practical Pioneer imagines a better way, builds its first tangible expression, and invites others into the adventure. At their best, they make innovation participatory and practical. Under stress, novelty replaces faithfulness, enthusiasm outruns capacity, and teams inherit the cost of unfinished beginnings.","sigStrengthName":"Participatory Innovation","sigStrengthDesc":"","sigParadox":"Generating momentum without abandoning what the momentum started","devQuestion":"Can I remain faithful when innovation becomes implementation and excitement becomes ordinary responsibility?","formationPractices":["Define the problem before announcing the innovation.","Set success, failure, and learning criteria for every pilot.","Limit the number of active experiments.","Ask who will own the work after launch.","Publicly name the cost and uncertainty.","Finish or formally close one initiative before beginning another.","Invite operational critique without labeling it negativity.","Celebrate maintenance and refinement as creative faithfulness."],"leadershipStyleName":"The Participatory Innovator"},{"num":25,"name":"The Compassionate Builder","slug":"compassionate-builder","gifts":["catalyst","servant","lover"],"pressure":{"name":"The Unspoken Bill","line":"Work done for people who are suffering, counted silently, and ended in silence.","missing":{"gift":"host","text":"Giving is the missing brake. A Host resources the work so it does not have to be paid for out of the builder — this archetype consistently funds compassion with its own body."},"pattern":"rotating","stages":[{"text":"The wrong sharpens, the work consolidates, and the cost is absorbed silently. They are angry about the suffering, doing most of the work about it, and saying nothing about either."},{"text":"The indictment, the ledger and the plea run at once. The people being served receive urgency, unspoken debt and hurt in the same interaction, and can only respond to one of the three."},{"text":"The scorch, the collapse and the silence land together. Work that existed for suffering people ends because the person doing it was suffering and had no gift that would say so."}],"tell":"This archetype confronts systems and never confronts people. Ask directly what they need; they will not volunteer it."},"essence":"To recognize the human suffering created by a broken reality, pioneer a more healing alternative, and build a tangible solution that restores dignity.","section":"Section 6: The Groundbreakers (Balanced Triads · Catalyst-Led)","axisSignature":"1 Why · 1 How · 1 Who","websiteSummary":"The Compassionate Builder feels the suffering created by what is broken, imagines a more humane possibility, and builds a tangible solution. At their best, they practice human-centered innovation that restores dignity and agency. Under stress, compassion becomes over-responsibility, innovation becomes rescuing, and relentless work replaces grief.","sigStrengthName":"Human-Centered Innovation","sigStrengthDesc":"","sigParadox":"Building from compassion without working to escape compassion’s grief","devQuestion":"Can I remain emotionally present to suffering without believing I must personally build the entire answer?","formationPractices":["Include affected people as co-designers with real authority.","Name the grief before proposing the solution.","Define the specific problem the project can address.","Ask whether building is replacing feeling.","Establish limits on personal work and availability.","Create a feedback process that does not depend upon gratitude.","Build in a way that increases local ownership.","Receive help before exhaustion makes it unavoidable.","Rest as an act of trust rather than a retreat from compassion."],"leadershipStyleName":"The Human-Centered Builder"},{"num":26,"name":"The Generous Pioneer","slug":"generous-pioneer","gifts":["catalyst","enthusiast","host"],"pressure":{"name":"The Recalled Backing","line":"A bold bet, sold hard, then pulled when the enthusiasm and the returns run out together.","missing":{"gift":"erudite","text":"Teaching is the missing brake. An Erudite tests whether the bet is sound before it needs defending — this archetype's conviction and charm can carry a weak idea a very long way."},"pattern":"rotating","stages":[{"text":"The bet hardens into certainty, the pitch brightens, and the money starts being measured. Two gifts are selling while the third is quietly getting cold feet, and nobody hears about the third."},{"text":"Indictment, spin and leverage combine. Doubters are challenged, difficulties reframed, and the funding acquires conditions — so the people who went all in are now managing the person who asked them to."},{"text":"The burn, the vanishing and the closed hand arrive together. Support is withdrawn suddenly and framed as discipline, leaving people holding something they were told to commit to."}],"tell":"Watch the gap between how confident the pitch is and how conditional the money has become. That gap is the descent."},"essence":"To pioneer a compelling new possibility, rally people around its promise, and mobilize the resources needed to bring it to life.","section":"Section 6: The Groundbreakers (Balanced Triads · Catalyst-Led)","axisSignature":"1 Why · 1 How · 1 Who","websiteSummary":"The Generous Pioneer imagines a bold new possibility, inspires people to believe in it, and mobilizes the resources required for launch. At their best, they practice catalytic investment that expands others’ agency. Under stress, enthusiasm overpromises, generosity seeks control, and innovation becomes attached to the founder’s identity.","sigStrengthName":"Catalytic Investment","sigStrengthDesc":"","sigParadox":"Generously launching the future without needing to own it","devQuestion":"Can I provide catalytic support without requiring the future to remain in my image?","formationPractices":["Define the problem before funding the solution.","Separate financial support from decision-making rights.","Require realistic stewardship plans for new initiatives.","Fund something without receiving public recognition.","Invite a trusted critic to evaluate the proposal.","Tell supporters the costs and uncertainties.","Establish review points before increasing investment.","Practice blessing an initiative that develops differently than imagined."],"leadershipStyleName":"The Catalytic Patron"},{"num":27,"name":"The Resourced Healer","slug":"resourced-healer","gifts":["catalyst","host","lover"],"pressure":{"name":"The Conditional Rescue","line":"Help offered urgently, then attached to terms, then withdrawn along with the helper.","missing":{"gift":"strategist","text":"Leadership is the missing brake. A Strategist builds the help into something that runs without the healer's presence — otherwise every rescue depends on one person's ongoing goodwill."},"pattern":"rotating","stages":[{"text":"The need sharpens, the help starts being measured, and the helper absorbs whatever it costs. Intervention accelerates while the willingness to fund it quietly contracts."},{"text":"Indictment, leverage and plea combine into help that arrives urgently, carries terms, and comes with an ache the recipient is somehow responsible for."},{"text":"The scorch, the closed hand and the silence land together. The rescue and the rescuer are withdrawn at once, and the person being helped is left worse off than before it started."}],"tell":"When help starts requiring a particular response from the person receiving it, stage two has arrived."},"essence":"To identify the conditions producing suffering, pioneer a more healing alternative, and build or fund the resources through which restoration can occur.","section":"Section 6: The Groundbreakers (Balanced Triads · Catalyst-Led)","axisSignature":"1 Why · 1 How · 1 Who","websiteSummary":"The Resourced Healer identifies conditions that sustain suffering, pioneers more humane responses, and builds or funds environments of restoration. At their best, they expand access, dignity, and agency. Under stress, compassion becomes rescuing, provision becomes control, and the healer assumes responsibility for another person’s recovery.","sigStrengthName":"Restorative Institution-Building","sigStrengthDesc":"","sigParadox":"Resourcing healing without controlling another person’s recovery","devQuestion":"Can I create conditions for healing without claiming ownership of the healing process?","formationPractices":["Include recipients in governance and design.","Review whether funding conditions preserve agency.","Practice accompanying without rescuing.","Distinguish relapse or slow progress from failure.","Receive personal care rather than only providing it.","Fund approaches that do not increase your influence.","Build transparent outcome and feedback systems.","Ask whether the institution remains more committed to healing than survival."],"leadershipStyleName":"The Restorative Founder"},{"num":28,"name":"The Meticulous Motivator","slug":"meticulous-motivator","gifts":["servant","erudite","enthusiast"],"pressure":{"name":"The Corrected Cheer","line":"Doing everything, correcting everyone, and then simply not being there.","missing":{"gift":"strategist","text":"Leadership is the missing brake. A Strategist distributes the work before it consumes the person doing it — this archetype will carry an unsustainable load indefinitely without ever flagging it."},"pattern":"silent-drift","stages":[{"text":"The details accumulate, the standards acquire caveats, and the energy stays high. Everything runs beautifully, and the person running it is the only one who knows what that costs."},{"text":"Tally, correction and spin run together: encouragement with an amendment attached, delivered by someone keeping a private account of what they are carrying."},{"text":"The collapse, the seal and the vanishing arrive at once, and both the details and the morale go with them. The gap left behind is much larger than anyone had estimated."}],"tell":"When encouragement starts arriving with corrections attached, the accumulation underneath is already well advanced."},"essence":"To make difficult learning and skilled work approachable through accurate instruction, practical assistance, and encouraging reinforcement.","section":"Section 7: The Wise Stewards (Balanced Triads · Erudite-Led)","axisSignature":"1 Why · 1 How · 1 Who","websiteSummary":"The Meticulous Motivator combines accurate knowledge, practical instruction, and encouraging reinforcement to make mastery approachable. At their best, people learn difficult things without feeling small. Under stress, detail overwhelms, help becomes rescuing, and encouragement obscures necessary correction.","sigStrengthName":"Encouraging Mastery","sigStrengthDesc":"","sigParadox":"Helping people succeed without making their success dependent upon your help","devQuestion":"Can I support a learner through difficulty without removing the struggle through which mastery develops?","formationPractices":["Ask the learner to demonstrate before offering help.","Give concise, behaviorally specific feedback.","Allow manageable frustration.","Reduce assistance as competence increases.","Identify the minimum knowledge required for the next step.","Separate being kind from being approving.","Ask learners to evaluate their own performance first.","Celebrate independence more than gratitude."],"leadershipStyleName":"The Encouraging Instructor"},{"num":29,"name":"The Wise Caretaker","slug":"wise-caretaker","gifts":["servant","erudite","lover"],"pressure":{"name":"The Careful Withdrawal","line":"Care given precisely, then defended precisely, then withdrawn without explanation.","missing":{"gift":"enthusiast","text":"Encouragement is the missing brake. An Enthusiast keeps the relationship warm enough to hold a correction — without it, every piece of feedback in either direction costs more than it should."},"pattern":"silent-drift","stages":[{"text":"The care expands, the judgment is withheld, and the tension is absorbed. Three silent gifts, all straining, none of which will announce anything."},{"text":"The tally, the precise correction and the plea combine into care that is thoughtful, faintly reproachful and quietly wounded — a combination almost impossible to respond to well."},{"text":"The collapse, the wall and the silence land together, and the withdrawal is final, well-reasoned and unexplained. No one is given a reason, because giving one would mean asking for something."}],"tell":"Watch for care that starts being defended rather than simply given. That shift is the earliest visible thing."},"essence":"To offer care that accurately understands the need, responds with practical competence, and preserves the dignity of the person receiving it.","section":"Section 7: The Wise Stewards (Balanced Triads · Erudite-Led)","axisSignature":"1 Why · 1 How · 1 Who","websiteSummary":"The Wise Caretaker combines careful understanding, emotional attunement, and practical service to provide care that genuinely fits. At their best, people feel both known and competently supported. Under stress, care becomes over-analysis, service becomes self-erasure, and personal needs remain hidden until exhaustion takes over.","sigStrengthName":"Discerning Care","sigStrengthDesc":"The Wise Caretaker often recognizes the difference between what a person requests, what they appear to need, and what will genuinely support flourishing.","sigParadox":"Understanding everyone’s needs while remaining silent about their own","devQuestion":"Can I believe that my needs deserve the same careful attention I give to others?","formationPractices":["State one personal need each day.","Ask permission before offering help.","Decide what information is sufficient for action.","Use a team for complex or recurring care.","Practice receiving without immediately serving.","Communicate limits before exhaustion.","Let another person make a choice you would not recommend.","Apply the same compassion and discernment inward."],"leadershipStyleName":"The Discerning Caregiver"},{"num":30,"name":"The Prudent Mentor","slug":"prudent-mentor","gifts":["erudite","enthusiast","host"],"pressure":{"name":"The Deferred Investment","line":"A judgment never quite delivered, a reassurance offered instead, and support quietly discontinued.","missing":{"gift":"catalyst","text":"Prophecy is the missing brake. A Catalyst forces the honest verdict the prudence keeps postponing — this archetype's kindness reliably delays the one conversation that would have helped."},"pattern":"silent-drift","stages":[{"text":"The verdict is withheld, the warmth increases, and the investment starts being measured. The mentee is being encouraged and quietly reassessed at the same time, and is told about only one of those."},{"text":"Correction, spin and leverage produce a relationship in which support is conditional on something that has never been stated. The mentee is being tested against a bar they have not been shown."},{"text":"The seal, the vanishing and the withdrawn support arrive together. The person on the other end never learns what the actual judgment was, which is the specific cruelty of this one."}],"tell":"Ask this archetype to say the verdict plainly. How hard it is to get a plain answer is the measurement."},"essence":"To recognize potential wisely, strengthen it through encouragement and insight, and provide the opportunities and resources through which it can flourish.","section":"Section 7: The Wise Stewards (Balanced Triads · Erudite-Led)","axisSignature":"1 Why · 1 How · 1 Who","websiteSummary":"The Prudent Mentor recognizes potential, strengthens it through wise encouragement, and provides concrete opportunities for development. At their best, investment expands another person’s freedom and contribution. Under stress, guidance becomes prescription, resources become leverage, and mentoring produces emotional debt.","sigStrengthName":"Empowering Sponsorship","sigStrengthDesc":"The Prudent Mentor can identify promising people and give them the support needed to develop beyond their current circumstances.","sigParadox":"Investing deeply without owning the return","devQuestion":"Can I help someone flourish into their calling rather than flourish according to my preferred image?","formationPractices":["Ask the mentee to define success.","Clarify all conditions before providing resources.","Invest anonymously when possible.","Sponsor someone outside your familiar social pattern.","Invite feedback about the relational power dynamic.","Bless a path you would not personally choose.","Celebrate independence and reduced reliance.","Evaluate whether access is being distributed fairly."],"leadershipStyleName":"The Developmental Sponsor"},{"num":31,"name":"The Benevolent Counselor","slug":"benevolent-counselor","gifts":["erudite","host","lover"],"pressure":{"name":"The Priced Confidence","line":"Wisdom held back, help given with terms, and a counselor who stopped answering.","missing":{"gift":"catalyst","text":"Prophecy is the missing brake. A Catalyst names the dynamic while both parties can still hear it — this archetype tends to fund what it should have confronted."},"pattern":"silent-drift","stages":[{"text":"The counsel is withheld, the help starts being measured, and the discomfort is absorbed. Wisdom, resources and feeling all present, all held back, none announced."},{"text":"Correction, leverage and plea combine: help that carries terms, advice too carefully worded to act on, and hurt that neither party can locate the source of."},{"text":"The seal, the closed hand and the silence land together. They stop returning the call, and the person who needed them has no idea which of the three things they did wrong."}],"tell":"When money or practical help starts substituting for the conversation, the descent is underway."},"essence":"To offer compassionate wisdom together with the tangible resources and relational support that help people rebuild their lives.","section":"Section 7: The Wise Stewards (Balanced Triads · Erudite-Led)","axisSignature":"1 Why · 1 How · 1 Who","websiteSummary":"The Benevolent Counselor pairs compassionate wisdom with tangible resources that help people rebuild. At their best, counsel and provision increase dignity, responsibility, and freedom. Under stress, wisdom becomes prescription, generosity produces obligation, and care keeps people dependent.","sigStrengthName":"Resourced Wisdom","sigStrengthDesc":"","sigParadox":"Providing meaningful help without becoming the owner of another person’s next step","devQuestion":"Can I offer wisdom and resources without requiring the recipient to use them exactly as I would?","formationPractices":["Ask the recipient to define the desired outcome.","Clarify all conditions before offering resources.","Separate counsel from material support where appropriate.","Offer options rather than a single required path.","Establish boundaries around repeated assistance.","Review whether support is increasing agency.","Practice giving without requiring access or gratitude.","Build relationships not organized around the helping role."],"leadershipStyleName":"The Restorative Advisor"},{"num":32,"name":"The Inspirational Implementer","slug":"inspirational-implementer","gifts":["servant","enthusiast","strategist"],"pressure":{"name":"The Overloaded Engine","line":"Carrying it all, keeping morale up about it, and finally running it alone in silence.","missing":{"gift":"lover","text":"Mercy is the missing brake. A Lover registers what the carrying is costing before it hardens — this archetype's own reporting on its own state is systematically unreliable."},"pattern":"rotating","stages":[{"text":"The execution consolidates, the morale stays high, and the plan tightens. The team is encouraged, the work is being absorbed by one person, and the reporting has quietly stopped being accurate."},{"text":"Tally, spin and override run together. The mood in the room and the state of the work diverge, and the person maintaining both is the only one who can see the gap."},{"text":"The collapse, the vanishing and the freeze arrive at once. The engine that carried the operation stops, and everyone discovers simultaneously that there was no second engine."}],"tell":"Compare their report on their own capacity with the volume they are actually carrying. The divergence is the measurement."},"essence":"To guide teams toward meaningful results by combining clear direction, practical execution, and an encouraging culture of shared accomplishment.","section":"Section 8: The Kingdom Builders (Balanced Triads · Strategist-Led)","axisSignature":"1 Why · 1 How · 1 Who","websiteSummary":"The Inspirational Implementer combines strategic direction, practical execution, and encouraging team culture. At their best, people understand the goal, enjoy contributing, and deliver together. Under stress, positivity hides problems, service becomes over-functioning, and accountability is delayed.","sigStrengthName":"Energized Execution","sigStrengthDesc":"","sigParadox":"Maintaining morale without using positivity to hide problems","devQuestion":"Can I preserve hope while naming clearly what is not working?","formationPractices":["Name one difficult reality before offering encouragement.","Clarify every task’s owner and deadline.","Stop doing one task that belongs to someone else.","Ask the team to identify what is not working.","Replace generic praise with specific recognition.","Build recovery time into project completion.","Reduce scope before increasing personal sacrifice.","Address underperformance while the relationship is still warm."],"leadershipStyleName":"The Morale-Building Operator"},{"num":33,"name":"The Protective Architect","slug":"protective-architect","gifts":["servant","strategist","lover"],"pressure":{"name":"The Fortified Care","line":"Protection built by hand, imposed without consent, and then abandoned in hurt.","missing":{"gift":"enthusiast","text":"Encouragement is the missing brake. An Enthusiast keeps the protected people feeling chosen rather than managed — the same safeguards, received as care instead of as control."},"pattern":"rotating","stages":[{"text":"The safeguards get built quietly, the grip tightens, and the cost is absorbed. Protection is being constructed by someone who will not mention constructing it."},{"text":"The ledger, the override and the plea combine into protection imposed without consent, followed by hurt that it was not appreciated. The protected feel managed, and then guilty."},{"text":"The collapse, the freeze and the silence land together. The structure stays standing and its keeper is gone, and the people inside it never knew it was held up by one person."}],"tell":"Watch for a safeguard put in place without anyone being asked. That first unilateral protection is stage two arriving early."},"essence":"To design and build effective systems while protecting the dignity, capacity, and well-being of the people doing the work.","section":"Section 8: The Kingdom Builders (Balanced Triads · Strategist-Led)","axisSignature":"1 Why · 1 How · 1 Who","websiteSummary":"The Protective Architect builds effective systems while guarding the dignity and capacity of the people within them. At their best, excellence and care strengthen one another. Under stress, protection becomes control, service becomes over-functioning, and people remain dependent rather than empowered.","sigStrengthName":"Humane Systems Design","sigStrengthDesc":"The Protective Architect can create environments in which excellence and well-being reinforce rather than oppose one another.","sigParadox":"Protecting people without taking away their ownership of difficult work","devQuestion":"Can I protect people from exploitation without protecting them from every challenge through which competence and resilience develop?","formationPractices":["Include frontline contributors in system design.","Define the difference between difficult work and harmful overload.","Return one responsibility you have absorbed.","Delegate authority alongside tasks.","Make workload visible across the team.","State hard expectations with compassion.","Let someone learn through a recoverable mistake.","Evaluate both outcomes and human impact."],"leadershipStyleName":"The Humane Systems Builder"},{"num":34,"name":"The Kingdom Cultivator","slug":"kingdom-cultivator","gifts":["enthusiast","host","strategist"],"pressure":{"name":"The Managed Garden","line":"A community grown warmly, resourced conditionally, and finally governed by one person alone.","missing":{"gift":"lover","text":"Mercy is the missing brake. A Lover knows which specific person in the community has stopped flourishing — a signal that disappears the moment community health becomes an aggregate."},"pattern":"rotating","stages":[{"text":"The gathering intensifies, the resources start being measured, and governance tightens. A community that felt like a family begins, imperceptibly, to become an organisation."},{"text":"Spin, leverage and override combine. Belonging becomes conditional on terms that are never published, and warmth becomes the medium through which decisions are delivered rather than made."},{"text":"The vanishing, the closed hand and the freeze arrive together. The garden is governed by one person who is no longer in it, and the people who joined for the warmth leave without a stated reason."}],"tell":"When you can no longer tell whether an invitation is hospitality or strategy, stage two has started."},"essence":"To grow healthy organizations by aligning compelling purpose, generous resources, strategic structure, and a culture in which people want to participate.","section":"Section 8: The Kingdom Builders (Balanced Triads · Strategist-Led)","axisSignature":"1 Why · 1 How · 1 Who","websiteSummary":"The Kingdom Cultivator aligns purpose, resources, strategy, and culture so organizations can flourish over time. At their best, growth increases shared participation and life. Under stress, culture becomes managed, resources reinforce loyalty, and organizational optics eclipse honest reality.","sigStrengthName":"Organizational Cultivation","sigStrengthDesc":"","sigParadox":"Cultivating a living culture without managing every expression of it","devQuestion":"Can I shape the conditions for healthy culture without controlling what people are allowed to think, feel, or say?","formationPractices":["Create a confidential channel for dissent.","Measure health using more than growth and participation.","Ask where public culture and private experience diverge.","Allocate resources through transparent criteria.","communicate one meaningful uncertainty honestly.","Let another leader shape culture differently.","Prune an initiative that no longer serves the mission.","Conduct listening sessions without defending the organization.","Celebrate faithfulness that is not publicly impressive."],"leadershipStyleName":"The Organizational Cultivator"},{"num":35,"name":"The Benevolent Leader","slug":"benevolent-leader","gifts":["host","strategist","lover"],"pressure":{"name":"The Measured Mercy","line":"Generosity that starts counting, leadership that stops asking, and compassion that closes the door.","missing":{"gift":"catalyst","text":"Prophecy is the missing brake. A Catalyst says the thing the kindness is protecting everyone from — this archetype's decline is almost entirely composed of unsaid true things."},"pattern":"rotating","stages":[{"text":"The generosity starts being weighed, the plan tightens, and the resulting friction is absorbed rather than named. Provision, authority and feeling all contracting quietly at once."},{"text":"Leverage, override and plea combine into leadership that gives conditionally, decides unilaterally, and is wounded that neither is received warmly. Nobody can respond to all three."},{"text":"The closed hand, the freeze and the silence land together. The most generous person in the organisation stops giving, stops consulting and stops speaking, in roughly that order and without explanation."}],"tell":"Notice the first time generosity is mentioned rather than simply given. Naming it is the beginning of counting it."},"essence":"To lead people toward a meaningful future while providing the resources, protection, and relational care that help them flourish along the journey.","section":"Section 8: The Kingdom Builders (Balanced Triads · Strategist-Led)","axisSignature":"1 Why · 1 How · 1 Who","websiteSummary":"The Benevolent Leader combines strategic direction, generous provision, and compassionate protection. At their best, people receive the support and authority needed to flourish. Under stress, care becomes paternalism, resources create dependence, and protection prevents the struggle through which maturity develops. Appendix","sigStrengthName":"Resourced, People-Centered Direction","sigStrengthDesc":"","sigParadox":"Providing security without making people dependent upon the provider","devQuestion":"Can I care enough to let people carry real responsibility, face necessary struggle, and become less dependent upon me?","formationPractices":["Return one decision to the person who should own it.","Ask whether each provision increases capacity.","Let a recoverable consequence remain.","Publish transparent resource-allocation criteria.","Give emerging leaders real authority.","Resist solving a problem before others attempt it.","Invite critique from people who do not depend upon your resources.","Develop a succession plan.","Practice presence without intervention."],"leadershipStyleName":"The Provisioning Shepherd"}];
window.QUESTIONS = {"likert":[{"id":1,"text":"I naturally think in terms of long-range goals and strategic plans.","gift":"strategist"},{"id":2,"text":"I am energized by challenging the status quo to bring about necessary change.","gift":"catalyst"},{"id":3,"text":"I feel most satisfied when I have completed a practical task with excellence.","gift":"servant"},{"id":4,"text":"Building many positive, encouraging relationships is one of my highest priorities.","gift":"enthusiast"},{"id":5,"text":"My primary drive is to create an environment where people feel emotionally safe and accepted.","gift":"lover"},{"id":6,"text":"I feel a deep need for quiet time alone to think, process, and recharge.","gift":"erudite"},{"id":7,"text":"I am a good manager of resources (time, money, people) and use them wisely.","gift":"host"},{"id":8,"text":"I am driven to build systems and structures that create order and ensure long-term success, and will see my plans come to fruition, even if it takes days, months, or years.","gift":"strategist"},{"id":9,"text":"When I see a problem, my first instinct is to identify the root truth, even if it's uncomfortable.","gift":"catalyst"},{"id":10,"text":"People describe me as meticulous and conscientious in the tasks I complete for them.","gift":"servant"},{"id":11,"text":"I often verbally affirm others' potential and strengths in all spheres of my life.","gift":"enthusiast"},{"id":12,"text":"I have a deep, intuitive sense of the emotional state of others and feel moved to undo their aloneness in places of pain.","gift":"lover"},{"id":13,"text":"Before I accept something as fact, I feel compelled to research and validate it for myself.","gift":"erudite"},{"id":14,"text":"I get great joy, and am gifted at being hospitable and making people feel comfortable and cherished.","gift":"host"},{"id":15,"text":"I am a natural leader and take a long-term view of leadership and the development of others.","gift":"strategist"},{"id":16,"text":"I am more concerned with integrity and authenticity than with keeping everyone comfortable.","gift":"catalyst"},{"id":17,"text":"It frustrates me when I see people not doing their fair share of the work.","gift":"servant"},{"id":18,"text":"I am energized by rallying people together around a hopeful, positive vision.","gift":"enthusiast"},{"id":19,"text":"I am known for my long-suffering unconditional love and acceptance.","gift":"lover"},{"id":20,"text":"I research deeper and more complex topics than most others just for the sake of knowing the information.","gift":"erudite"},{"id":21,"text":"I usually have what others need, such as snacks, drinks, or other useful items, such as tissues, before others know that they need it.","gift":"host"},{"id":22,"text":"I have goals in place and don't like to deviate from them until they are completed.","gift":"strategist"},{"id":23,"text":"I am a pioneering spirit, always having new and innovative ideas and solutions.","gift":"catalyst"},{"id":24,"text":"People can count on me to be dependable and to finish the tasks I start.","gift":"servant"},{"id":25,"text":"I feel fulfilled when I can inspire and rally others to become passionate about what I am most passionate about at a given time.","gift":"enthusiast"},{"id":26,"text":"I tend to deescalate conflict and am often a peacemaker.","gift":"lover"},{"id":27,"text":"I am frustrated by superficial conversations that don't interest me and prefer deep, intellectually stimulating discussions.","gift":"erudite"},{"id":28,"text":"I am super resourceful.","gift":"host"},{"id":29,"text":"I have little patience for activities that do not align with the main goal or vision.","gift":"strategist"},{"id":30,"text":"I feel compelled to speak up against injustice or hypocrisy.","gift":"catalyst"},{"id":31,"text":"I show my love for others by taking practical action to meet their tangible needs.","gift":"servant"},{"id":32,"text":"I am naturally optimistic and believe the best about people and situations.","gift":"enthusiast"},{"id":33,"text":"I can become emotionally overwhelmed because I sometimes absorb the pain of others.","gift":"lover"},{"id":34,"text":"I prefer to be alone studying the things I am passionate about or explaining them to interested individuals.","gift":"erudite"},{"id":35,"text":"I enjoy stewarding and multiplying resources so I can be more generous.","gift":"host"},{"id":36,"text":"My motto could be, \"Good leaders create a vision, articulate the vision, passionately own the vision, and relentlessly drive it to completion.\" - Jack Welch.","gift":"strategist"},{"id":37,"text":"I have a strong inner sense of what is right and wrong.","gift":"catalyst"},{"id":38,"text":"I often notice and move to meet the practical needs in a room before anyone else does.","gift":"servant"},{"id":39,"text":"I have a strong intuition about interpersonal dynamics and work to build bridges between people.","gift":"enthusiast"},{"id":40,"text":"I am fiercely protective of the vulnerable and instinctively shield them from harm.","gift":"lover"},{"id":41,"text":"I am not easily swayed by peer pressure or others' approval, as I have strong convictions and desires.","gift":"erudite"},{"id":42,"text":"I view the resources I have as something I've been entrusted with for the benefit of others.","gift":"host"},{"id":43,"text":"I excel at architecting a long-term plan and then delegating to the right people to bring that vision to reality.","gift":"strategist"},{"id":44,"text":"I am compelled to challenge the status quo and uproot broken systems to achieve radical, not just incremental, transformation.","gift":"catalyst"},{"id":45,"text":"I feel most fulfilled after a hard day of tangible, productive work.","gift":"servant"},{"id":46,"text":"I'm energized by rallying people together, using fun and celebration to build connections and inspire a shared sense of optimism.","gift":"enthusiast"},{"id":47,"text":"I feel most loved when someone listens to me with their whole heart and understands my feelings.","gift":"lover"},{"id":48,"text":"I feel most loved when someone engages me in a deeply intellectual conversation.","gift":"erudite"},{"id":49,"text":"I constantly am thinking about how myself and others can engage in wise financial stewardship.","gift":"host"}],"forcedChoice":[{"id":50,"stem":"I am more driven to...","a":"Challenge a broken system to get to the truth.","b":"Diligently complete the tasks needed to keep the current system running.","giftA":"catalyst","giftB":"servant"},{"id":51,"stem":"I am more driven to...","a":"Inspire a group of people with a hopeful, positive vision.","b":"Confront a group with an uncomfortable reality that leads to transformation.","giftA":"enthusiast","giftB":"catalyst"},{"id":52,"stem":"I am more driven to...","a":"Speak a hard truth, even if it causes emotional discomfort.","b":"Protect someone's feelings, even if it means avoiding a hard truth.","giftA":"catalyst","giftB":"lover"},{"id":53,"stem":"When leading, my priority is...","a":"Ensuring the team stays the course on a well-thought-out master plan.","b":"Allowing for disruptive innovation that might improve upon the master plan.","giftA":"strategist","giftB":"catalyst"},{"id":54,"stem":"I am more drawn to...","a":"A deep, analytical dive into a complex subject.","b":"A bold, pioneering adventure that challenges my limits.","giftA":"erudite","giftB":"catalyst"},{"id":55,"stem":"My focus is more on...","a":"Wisely stewarding resources to fund a bold, risky, but potentially revolutionary idea or adventure.","b":"Wisely stewarding resources to ensure long-term stability and security.","giftA":"catalyst","giftB":"host"},{"id":56,"stem":"I prefer to show support by...","a":"Cheerfully rallying and encouraging the person.","b":"Practically helping them with their to-do list.","giftA":"enthusiast","giftB":"servant"},{"id":57,"stem":"I believe love is best expressed by...","a":"Providing tangible help and practical solutions.","b":"Providing a safe, empathetic presence for someone's emotions.","giftA":"servant","giftB":"lover"},{"id":58,"stem":"In a group project, I focus on...","a":"The long-term vision and overall strategy.","b":"The immediate tasks that need to be done right now.","giftA":"strategist","giftB":"servant"},{"id":59,"stem":"I am more likely to be...","a":"Frustrated by inaction and analysis paralysis.","b":"Frustrated by rushed decisions made without thorough research.","giftA":"servant","giftB":"erudite"},{"id":60,"stem":"When giving a gift, I am more concerned with...","a":"Ensuring everyone contributes fairly and the gift is practical.","b":"Ensuring the gift is generous, empowering, and makes the recipient feel cherished.","giftA":"servant","giftB":"host"},{"id":61,"stem":"A healthy relationship requires...","a":"Deep emotional safety and unconditional acceptance.","b":"Uplifting joy and mutual celebration.","giftA":"lover","giftB":"enthusiast"},{"id":62,"stem":"I am more inclined to...","a":"Let my decisions be guided by the emotional needs of the people involved.","b":"Let my decisions be guided by the objective goals of the plan.","giftA":"lover","giftB":"strategist"},{"id":63,"stem":"My approach to problems is more...","a":"Analytical and logical, based on verifiable facts.","b":"Empathetic and intuitive, based on people's feelings.","giftA":"erudite","giftB":"lover"},{"id":64,"stem":"When considering a large donation, I prioritize...","a":"The immediate emotional relief and comfort it will bring to an individual.","b":"The long-term strategic impact and stewardship of the organization receiving it.","giftA":"lover","giftB":"host"},{"id":65,"stem":"I am more energized by...","a":"Creating a detailed, systematic plan to achieve a goal.","b":"Inspiring and rallying a team towards a shared objective.","giftA":"strategist","giftB":"enthusiast"},{"id":66,"stem":"I find it more important to be...","a":"Intellectually rigorous and precise.","b":"Relationally warm and encouraging.","giftA":"erudite","giftB":"enthusiast"},{"id":67,"stem":"When planning an event, I focus more on...","a":"The relational atmosphere and ensuring people have fun and connect.","b":"The budget and resources, ensuring a high-quality experience through wise stewardship.","giftA":"enthusiast","giftB":"host"},{"id":68,"stem":"My leadership style is more focused on...","a":"Architecting brilliant, long-term systems and plans.","b":"Patiently mentoring individuals to help them master a subject.","giftA":"strategist","giftB":"erudite"},{"id":69,"stem":"I would rather...","a":"Build a detailed budget and investment plan.","b":"Build a comprehensive research paper with extensive citations.","giftA":"host","giftB":"erudite"},{"id":70,"stem":"When making a big decision, I trust...","a":"A strategic plan that lays out the path to a future goal.","b":"A prudent financial plan that ensures resources are used wisely.","giftA":"strategist","giftB":"host"}],"scenarios":[{"id":1,"stem":"A volunteer project you are on is missing deadlines and team morale is plummeting.","options":["Call an emergency meeting to re-architect the master plan, clarify the vision, and re-delegate tasks.","Privately check in with each team member to see how they are feeling, creating a safe space for them to voice concerns.","Find the biggest practical bottleneck and just start doing the work yourself to get momentum going again.","Directly confront the unspoken issue you believe is causing the failure, pushing for honesty to clear the air."],"gifts":["strategist","lover","servant","catalyst"]},{"id":2,"stem":"A close friend is devastated after being laid off from their job.","options":["Immediately start reminding them of their strengths, telling them this is a setup for a comeback, and painting a positive picture of their future.","Offer a significant and thoughtful financial gift to cover their expenses for a month, empowering them to search for a new job without stress.","Spend hours with them researching the job market, analyzing their resume, and helping them build a logical, data-driven plan for their job search.","Sit with them in their grief, listen without judgment, and let them know you are there for them no matter what, validating their feelings of loss and fear."],"gifts":["enthusiast","host","erudite","lover"]},{"id":3,"stem":"You are on the planning committee for a large community-wide charity event.","options":["Take charge of the budget and fundraising, ensuring every dollar is used wisely to create a high-quality, memorable, and generous experience.","Volunteer to be the MC or lead the welcoming committee, focusing on creating a fun, high-energy, and relational atmosphere.","Take on the role of overall event coordinator, developing the master timeline, defining roles for all teams, and making sure the event achieves its objective.","Sign up for the setup and teardown crew, quietly ensuring all the practical, hands-on work gets done with excellence."],"gifts":["host","enthusiast","strategist","servant"]},{"id":4,"stem":"You receive an unexpected financial windfall of $5,000.","options":["Use it to fund a bold, adventurous trip, or invest it in a high-risk, high-reward idea you believe in.","Put it toward a major long-term goal (like a down payment or a business plan), allocating it according to your life strategy.","Immediately think of a person or cause that could benefit and give a generous, empowering gift.","Spend it on a fantastic party or group vacation to create a lasting, joyful memory with the people you love."],"gifts":["catalyst","strategist","host","enthusiast"]},{"id":5,"stem":"You discover that a long-standing policy in your church or workplace is quietly hurting the very people it was meant to serve.","options":["Name the problem openly and press leadership for immediate, meaningful change, even if it ruffles feathers.","Quietly begin helping the people affected in practical, tangible ways while the debate plays out.","Research the policy's history and gather the data needed to build a careful, well-documented case for reform.","Seek out those who have been hurt, listen to their stories, and make sure no one carries the pain alone."],"gifts":["catalyst","servant","erudite","lover"]},{"id":6,"stem":"Your team is asked to launch a brand-new initiative from scratch, with wide freedom in how to begin.","options":["Challenge the assumptions behind the old way of doing things and cast a bold, disruptive vision for what this could become.","Study how others have done it—gathering research, best practices, and lessons learned before anything is decided.","Architect the master plan: phases, roles, milestones, and a clear picture of success at the end.","Take charge of resourcing it—securing the budget, space, and supplies so the team launches generously provided for."],"gifts":["catalyst","erudite","strategist","host"]},{"id":7,"stem":"A new family joins your community and seems overwhelmed by the transition.","options":["Show up with practical help: meals, moving boxes, school runs—whatever lightens their load this week.","Welcome them warmly, introduce them to everyone, and speak hope and excitement over their new chapter.","Make unhurried space to hear their story and keep checking in on how they are really doing.","Patiently orient them—explaining how everything works and thoroughly answering every question they have."],"gifts":["servant","enthusiast","lover","erudite"]}],"giftMax":{"catalyst":68,"servant":68,"enthusiast":68,"lover":68,"strategist":68,"erudite":68,"host":68}};
window.PRESSURE_MODEL = {"title":"The Three Descents","premise":"A gift under pressure does not switch off. It works harder in the wrong direction. What you see in a distressed person is not the absence of their gift — it is their gift aimed at the wrong target, usually at whoever is closest.","theology":"Romans 12 names the gifts as grace given, not merit earned. Which means the descent is never evidence that the gift was false. It is evidence that the gift is being operated by fear instead of by faith. The way back is never to suppress the gift. It is to return it to its source.","stages":[{"n":1,"name":"Strain","line":"The gift, intensified.","description":"The gift is still recognizable and still aimed at something real. It has simply lost its grace — it is louder, faster, and less patient than it should be. The person still believes they are serving. Others notice the edge and usually excuse it.","reversal":"Reversible in a single honest conversation. This is the cheapest place to intervene and the place almost everyone misses."},{"n":2,"name":"Distortion","line":"The gift, weaponized.","description":"The gift turns outward as a blade or a wall. It is now protecting the person rather than serving the room. Motives get assigned. People begin managing the distressed person instead of engaging them, which confirms every fear that put them here.","reversal":"Still reversible, but it now takes repair rather than clarification. Something was damaged and has to be named before it can be undone."},{"n":3,"name":"Captivity","line":"The gift, inverted.","description":"The gift turns on its owner. The pattern is no longer something the person does; it is something that runs them. The strength has become the identity, and the identity has become a cell. From inside, captivity feels like clarity — which is exactly what makes it so hard to leave.","reversal":"Not self-correcting. This stage requires someone outside the pattern who is willing to stay. Insight alone will not lift it."}],"laws":[{"title":"The descent is always downhill from a real strength","body":"No one arrives at Captivity through a flaw. They arrive through a gift that was never given anywhere safe to land. Treat the pattern as a wounded strength, not as a character defect, or the person will defend it — correctly."},{"title":"Everyone descends in their own language","body":"Two people in identical distress will look nothing alike. One gets louder, one goes silent, one gets busy, one gets charming. Reading distress requires knowing the person's gift, not scanning for a universal set of warning signs."},{"title":"The flare is a request, badly worded","body":"Under every distress behavior is an unmet need the person has stopped being able to ask for directly. The behavior is the ask. Answer the need and the behavior loses its job."},{"title":"Pressure narrows the range","body":"In a good week, people operate across several gifts. Under pressure, everyone collapses back to their first gift and runs its flare. This is why relationships that work fine in ordinary conditions come apart in hard ones — the hard week is a different relationship."}]};
window.ARCH_PRESSURE_MODEL = {"title":"Three Descents at Once","premise":"A single gift descends through Strain, Distortion and Captivity inside itself. An archetype does not run one descent — it runs three, in parallel. All three gifts strain together, distort together, and go captive together. What makes an archetype's distress distinctive is never the order the gifts break in; the top three are a set, not a sequence. It is what the three descents produce when they combine.","note":"None of this is a prediction that you will fail this way. It is a map of what your particular three gifts do to each other when they are all under load. The cheapest place to interrupt it is Strain, and Strain always looks like your gifts working properly — which is why the tell matters more than the theory.","missingPremise":"Every archetype is three gifts, which means four gifts are quiet. Under pressure that matters more than usual: the check that would catch this combination lives in the gifts the archetype does not lead with. This is the single most useful reason to keep people around you who are not like you.","patternPremise":"Some gifts aim their distress outward at people. Some bank it silently. Some conceal it and then leave. Which mix an archetype carries determines how its three descents synchronise — whether they compound, hide each other, or alternate."};
window.ARCH_PATTERNS = {"amplifying":{"name":"Amplifying","mix":"Two gifts aim outward","body":"Two of the three gifts point their distress at people, and they do not take turns — they compound. Each makes the other's pressure feel justified, so escalation is fast and the person experiences it as decisiveness.","visibility":"Visible early and from a distance. Everyone around them can see it. They cannot.","catch":"Ask them to name one person currently allowed to tell them no. If the answer takes a moment, it has started."},"hardening":{"name":"Hardening","mix":"One outward edge over a silent accumulation","body":"One gift pushes outward while two bank in silence. The visible edge is the smallest part of what is happening: behind it, work, resources or certainty are being accumulated and quietly withdrawn.","visibility":"People react to the edge and miss the accumulation, so the help aims at the wrong thing while the real problem keeps growing.","catch":"Do not respond to the sharpness. Ask what they have been carrying that they have not mentioned."},"rotating":{"name":"Rotating","mix":"One of each — outward, silent, concealed","body":"One gift presses, one holds, one hides. Under pressure this archetype does not have a single failure mode; it has three, and which appears depends on who is in the room and what the moment permits.","visibility":"Inconsistent from outside. Different people describe their distress completely differently, and all of them are right.","catch":"Compare notes with someone who sees them in a different setting. Neither of you has the whole picture alone."},"oscillating":{"name":"Oscillating","mix":"One outward, two concealed","body":"One gift pushes outward and two conceal. The result is alternation: a period of confrontation followed by a period of warmth or absence, with no stable middle.","visibility":"Whichever state you respond to, the other is coming — which makes them very hard to help, because help aimed at one phase arrives during the other.","catch":"Respond to the pattern, not the phase. Name the oscillation itself, gently, while things are calm."},"silent-drift":{"name":"Silent Drift","mix":"Two silent, one concealed — nothing aims outward","body":"Nothing in this archetype's distress aims at anyone. Two gifts accumulate quietly and the third conceals what is accumulating. There is no confrontation phase to alert anybody.","visibility":"Everything appears fine for a long time, then something ends without warning. The people closest are the most surprised.","catch":"It cannot be caught by watching. Ask directly and repeatedly, on a schedule, when nothing appears wrong."},"vanishing":{"name":"Vanishing","mix":"Two concealed, one silent","body":"Two gifts conceal and one accumulates. The concealment is not deception — it is the gift working: warmth offered, tension absorbed, the room kept comfortable while the cost is paid privately.","visibility":"The most beloved person in the room disappears, and nobody can point to when it started.","catch":"Ask what it cost them, specifically, and do not accept a cheerful answer the first time."},"sealing":{"name":"Sealing","mix":"All three silent","body":"All three gifts accumulate and none of them announce it. Work banked, resources banked, judgment banked — and each closes a different exit when it finally closes.","visibility":"The most invisible descent in the system. There is genuinely nothing to see until every door shuts at once.","catch":"Only structural help works: a standing, scheduled question from someone with permission to ask it. Nothing spontaneous will surface this."}};
window.GAP_BANDS = [{"range":"0 – 5","name":"Same Grain","line":"You understand each other without translating.","body":"Communication is nearly effortless and agreement comes fast. The risk is not friction; it is agreement. You share the same blind spot, the same trigger, and the same flare — so under pressure you will not check each other, you will amplify each other. This band needs an outsider more than any other.","watch":"Confirmation. When you agree instantly, ask who is missing from the conversation."},{"range":"6 – 11","name":"Working Gap","line":"Enough overlap to feel natural, enough difference to cover each other.","body":"The most productive band on the scale, and the most frequently taken for granted. You have real complementarity and enough shared instinct to access it without effort. Because it works without maintenance in ordinary conditions, most pairs here never build the protocol they will need in hard ones.","watch":"Complacency. This band holds until the first genuine crisis, then discovers it has no agreed process."},{"range":"12 – 17","name":"Wide Gap","line":"Misreading each other is the default, not the exception.","body":"Nearly every conflict here is a translation failure before it is a values failure. You are usually not disagreeing about what matters; you are disagreeing about what the other person just said. Handled deliberately, this is the range with the widest coverage — between you, very little is invisible.","watch":"Attribution. Before you conclude what they meant, ask. You will be wrong more often than your confidence suggests."},{"range":"18 – 24","name":"Inverted","line":"What you lead with is what they can barely see.","body":"Your first gift is at or near the bottom of their ranking, and theirs is at the bottom of yours. The highest friction and the highest complementarity in the same relationship. These pairs either become the strongest partnerships in an organization or the ones that end badly — the variable is whether the differences were made explicit early.","watch":"Goodwill as a strategy. Inverted pairs do not run on affection. They run on protocol: who decides what, in what order, by when."}];
window.BLIND_EXCHANGE = [{"gift":"catalyst","youSee":"A system that is plainly broken and a room that will not say so.","theyGet":"Nothing. The urgency does not register as information; it registers as instability.","youFeel":"Surrounded by complicity.","theyFeel":"Destabilized by someone who cannot leave things alone."},{"gift":"servant","youSee":"Undone work everywhere, and who is going to end up doing it.","theyGet":"No signal at all. The undone thing is not on their map as a thing.","youFeel":"Used, and quietly angry about a task they never knew existed.","theyFeel":"Blamed for a failure they cannot locate."},{"gift":"erudite","youSee":"Ground that has not been tested yet, and the cost of stepping on it anyway.","theyGet":"Delay. They are three moves ahead and cannot see what is being checked.","youFeel":"Rushed into a decision you will be blamed for.","theyFeel":"Held up by someone who will not commit."},{"gift":"enthusiast","youSee":"A room going cold and the relationships cooling with it.","theyGet":"Noise. The emotional temperature is not a variable they track.","youFeel":"Like you are the only one keeping this alive.","theyFeel":"Distracted from the actual subject."},{"gift":"host","youSee":"What this costs, where it came from, and who is carrying it.","theyGet":"Resources as ambient and roughly infinite.","youFeel":"Taken from.","theyFeel":"Audited."},{"gift":"strategist","youSee":"The sequence, the owner, and the date the whole thing fails without them.","theyGet":"The plan as optional background context.","youFeel":"Alone with the outcome.","theyFeel":"Managed."},{"gift":"lover","youSee":"Exactly how everyone in the room is actually doing.","theyGet":"A channel they do not receive. It is not that they dismiss it — they cannot detect it.","youFeel":"Unseen, in a room you are reading perfectly.","theyFeel":"Accused of a coldness they have no evidence of."}];
window.PAIR_COLLISIONS = [{"a":"catalyst","b":"servant","title":"The Uprooting and the Groundwork","loop":"The Catalyst sharpens and announces the change. The Servant absorbs the extra work it creates without mentioning it. The Catalyst reads the silence as agreement and pushes further. The Servant begins to tally. The Catalyst names the Servant's process as the obstacle and indicts it. The Servant collapses — and the collapse is the first the Catalyst has heard about any of it.","aSees":"Obstruction dressed up as diligence.","bSees":"Someone destroying work that was functioning, who will not be there for the rebuild.","breaker":"The Catalyst names the cost of the change out loud before announcing the change. The Servant states the cost as a number before absorbing it. Both moves are small; neither happens by accident."},{"a":"catalyst","b":"erudite","title":"Conviction and Corroboration","loop":"The Catalyst sharpens, needing validation now. The Erudite qualifies, because the case is not yet sound. The Catalyst reads the hedging as cowardice and indicts. The Erudite corrects — precisely, and with the receipts — then seals. Both are now certain, and neither is available.","aSees":"Analysis paralysis protecting someone who does not want to be accountable.","bSees":"Someone acting on a hunch and calling it revelation.","breaker":"Agree a deadline for the answer before the argument starts. The Catalyst gets a date; the Erudite gets a runway. Most of this conflict is a scheduling problem wearing a moral costume."},{"a":"catalyst","b":"enthusiast","title":"The Wound and the Warmth","loop":"The Catalyst sharpens and the room's temperature drops. The Enthusiast performs harder to bring it back. The Catalyst reads the warmth as evasion and indicts. The Enthusiast spins. The Catalyst scorches. The Enthusiast vanishes, and tells the story later as an escape.","aSees":"Someone who will sacrifice the truth to keep a room comfortable.","bSees":"Someone who will sacrifice people to make a point.","breaker":"The Catalyst delivers the hard thing and then stays for the repair. The Enthusiast hears the whole sentence before beginning to smooth it. Truth needs the warmth to be receivable; warmth needs the truth to be worth anything."},{"a":"catalyst","b":"host","title":"The Leap and the Ledger","loop":"The Catalyst sharpens: this has to happen, and it has to be resourced. The Host rations. The Catalyst indicts the caution as faithlessness. The Host funds it, but now with conditions attached. The Catalyst scorches. The Host closes the hand for good.","aSees":"Someone protecting a balance sheet while the thing that matters dies.","bSees":"Someone spending other people's resources on their own certainty.","breaker":"The Catalyst brings a number and a failure case, not only a conviction. The Host names the actual condition instead of slow-walking the decision. Ambiguity is what turns this into a character fight."},{"a":"catalyst","b":"strategist","title":"The Pivot and the Plan","loop":"The Catalyst sharpens: new truth, change course. The Strategist tightens. The Catalyst indicts the plan as an idol. The Strategist overrides. The Catalyst scorches. The Strategist freezes them out and finishes alone.","aSees":"Someone defending a plan that reality has already invalidated.","bSees":"Someone who mistakes every new idea for a revelation and has never finished anything.","breaker":"Separate 'is this true' from 'does this change the plan.' They are two different meetings. Run the first without deciding anything. Run the second with a decision rule agreed in advance, while everyone is calm.","note":"The highest-heat pair on the list. Both are certain, both are aimed at the outcome, and each experiences the other as the primary threat to it."},{"a":"catalyst","b":"lover","title":"The Blade and the Safety","loop":"The Catalyst sharpens. The Lover soothes and absorbs the impact. The Catalyst mistakes the smoothing for agreement and escalates. The Lover pleads — sideways, and days later. The Catalyst reads the emotion as manipulation and indicts. The Lover shuts down.","aSees":"Someone who cannot handle reality.","bSees":"Someone for whom being right matters more than the person in front of them.","breaker":"The Catalyst asks a question and waits through the entire silence for the answer. The Lover says the true thing in the moment rather than absorbing it.","note":"This pair does the most damage fastest, because the Lover's distress is silent and the Catalyst reads silence as consent. The Lover's real response arrives days after the Catalyst has moved on."},{"a":"servant","b":"erudite","title":"The Doing and the Deliberating","loop":"The Servant absorbs and starts the work. The Erudite qualifies, unwilling to endorse the approach yet. The Servant tallies — carrying this alone again. The Erudite corrects the work after it is finished. The Servant collapses.","aSees":"Someone thinking about the problem while other people solve it.","bSees":"Motion mistaken for progress, and work that will now have to be redone.","breaker":"The Erudite gives a provisional green light with a named review point. The Servant asks for the review before doing the work rather than after."},{"a":"servant","b":"enthusiast","title":"The Load and the Lift","loop":"The Servant absorbs. The Enthusiast performs — celebrates the team, generates the energy, picks nothing up. The Servant tallies. The Enthusiast turns the tally into a joke. The Servant collapses. The Enthusiast vanishes, hurt and genuinely bewildered.","aSees":"Someone who takes credit for the atmosphere while other people produce the results.","bSees":"Someone whose martyrdom makes the entire room heavy.","breaker":"The Enthusiast takes one concrete, unglamorous task and finishes it visibly. The Servant converts the resentment into a request within forty-eight hours instead of banking it."},{"a":"servant","b":"host","title":"Two Kinds of Giving","loop":"Both give. Both keep score. Under pressure each discounts the other's currency. The Servant absorbs labor; the Host rations resource. The Servant tallies — they wrote a check, I did the work. The Host leverages. Both withdraw, each privately certain they gave more.","aSees":"Generosity that costs nothing personal.","bSees":"Someone who does the visible task and calls it sacrifice while ignoring who paid for it.","breaker":"Each names the other's contribution in the other's own currency, specifically and out loud. 'That check meant this.' 'Those hours meant that.' The entire conflict is two ledgers that were never reconciled."},{"a":"servant","b":"strategist","title":"The Hands and the Plan","loop":"The Strategist tightens and assigns. The Servant absorbs. The Strategist reads capacity as availability and assigns more. The Servant tallies. The Strategist overrides the complaint as noise. The Servant collapses — with no warning that either of them would recognize as one.","aSees":"Someone who spends people and calls it leadership.","bSees":"Someone who never raised a hand and then broke.","breaker":"The Strategist asks for the number rather than the willingness: what would have to come off for this to fit? The Servant answers with a real limit instead of a yes.","note":"The most common burnout pair in any organization: a leader who assigns and a worker who has never once said no."},{"a":"servant","b":"lover","title":"The Quiet Pair","loop":"Both absorb. Both go silent. Neither asks. The Servant does more; the Lover insists nothing is wrong. Resentment accumulates on both sides with no visible surface. The Servant tallies through sighs; the Lover pleads through hints. Neither is answered, because neither asked. Both shut down.","aSees":"Someone who is upset about something and will not say what.","bSees":"Someone who is doing everything and will not say what they need.","breaker":"One of them has to ask a direct question and then wait through the silence. Nothing here resolves by escalation, because neither of them escalates.","note":"The least visible and most durable resentment on the list. This pair can run for a decade without a single raised voice and without a single honest sentence."},{"a":"erudite","b":"enthusiast","title":"Depth and Delivery","loop":"The Erudite qualifies. The Enthusiast simplifies it for the room. The Erudite corrects the simplification, publicly. The Enthusiast spins away from the correction. The Erudite seals. The Enthusiast vanishes.","aSees":"Someone flattening the truth for applause.","bSees":"Someone who would rather be precise than be understood.","breaker":"Build the message together with clear domains: the Erudite owns accuracy, the Enthusiast owns receivability, and neither overrides the other's territory.","note":"A genuine complement, wasted more often than any other pair on this list. Almost every idea that changed anything needed both of these people."},{"a":"erudite","b":"host","title":"The Study and the Spend","loop":"The Erudite qualifies. The Host reads it as an inability to commit and rations. The Erudite corrects the Host's reasoning. The Host attaches conditions. Both withdraw, each certain the other is the unserious one.","aSees":"Decisions made on instinct and cash flow rather than evidence.","bSees":"An inquiry with no end date that never produces anything to act on.","breaker":"Put a decision date and a decision rule on the calendar. The Erudite gets the interval; the Host gets the guarantee that it terminates."},{"a":"erudite","b":"strategist","title":"The Question and the Order","loop":"The Strategist tightens — the call has to be made now. The Erudite qualifies. The Strategist overrides and decides without them. The Erudite corrects afterward, from the record. The Strategist freezes them out of the next decision. The Erudite seals.","aSees":"An advisor who will not advise, and then critiques.","bSees":"A leader who wanted agreement rather than counsel.","breaker":"The Strategist asks for the best answer available by a stated time and commits to acting on it. The Erudite commits to producing one, clearly flagged as provisional. Both have to accept that a decision made on incomplete information is not a failure of process."},{"a":"erudite","b":"lover","title":"The Head and the Heart","loop":"The Lover soothes and does not say what is wrong. The Erudite answers the words and misses the signal entirely. The Lover pleads. The Erudite analyzes the feeling instead of receiving it. The Lover shuts down. The Erudite seals, having concluded the exchange was irrational.","aSees":"An emotional response with no argument inside it.","bSees":"Someone who treated their pain as a proposition to be evaluated.","breaker":"The Erudite says: tell me the feeling first, and I will not try to solve it yet. The Lover leads with the need instead of the story.","note":"Their information is genuinely in different formats. Both formats are real, and neither converts without effort."},{"a":"enthusiast","b":"host","title":"The Vision and the Cost","loop":"The Enthusiast performs and sells the possibility. The Host rations. The Enthusiast spins past the objection. The Host funds it with strings attached. The Enthusiast vanishes the moment the strings pull.","aSees":"Someone who kills momentum with a spreadsheet.","bSees":"Someone selling enthusiasm as though it were a plan, with someone else's money.","breaker":"The Enthusiast brings the cost alongside the vision, unprompted. The Host states the actual number and the actual condition instead of stalling."},{"a":"enthusiast","b":"strategist","title":"The Room and the Result","loop":"The Strategist tightens. The Enthusiast performs to restore morale. The Strategist reads it as noise and overrides. The Enthusiast spins. The Strategist freezes them out of the decision. The Enthusiast vanishes.","aSees":"Energy substituting for execution.","bSees":"A plan that will be executed flawlessly by people who have stopped caring.","breaker":"The Strategist gives the Enthusiast ownership of a real deliverable rather than of the atmosphere. The Enthusiast reports the number before reporting the mood."},{"a":"enthusiast","b":"lover","title":"Two Ways of Loving People","loop":"The Enthusiast performs and keeps it light. The Lover soothes and does not say the hard thing. The real issue is never raised. The Lover pleads sideways. The Enthusiast spins. The Lover shuts down. The Enthusiast vanishes, genuinely surprised that anything was wrong.","aSees":"A mood that changed without warning.","bSees":"Someone who was never actually present for the depth of it.","breaker":"Schedule the hard conversation, because neither of them will start it spontaneously. This pair does not need more warmth. It needs a calendar.","note":"Warm, easy, and quietly dangerous. Both are relational, both are conflict-averse, and both need to be wanted — which means nothing difficult ever gets said until it is too late to say it well."},{"a":"host","b":"strategist","title":"Stewardship and Command","loop":"The Strategist tightens — the plan requires the resource. The Host rations — the resource requires a return. The Strategist overrides the condition. The Host attaches a heavier one. The Strategist freezes. The Host withholds.","aSees":"Someone treating the mission as a portfolio.","bSees":"Someone treating their provision as an entitlement.","breaker":"Agree in advance what the resource is for and what evidence closes the loop. This conflict is almost always the absence of a stated return condition, not a disagreement about the mission."},{"a":"host","b":"lover","title":"The Gift and the Gesture","loop":"The Host rations. The Lover reads the withdrawal of provision as a withdrawal of love. The Lover soothes and asks for nothing. The Host reads the silence as not being needed. The Host withholds. The Lover shuts down.","aSees":"Someone who never says what they need and then seems wounded.","bSees":"Someone who gives things instead of presence.","breaker":"The Host gives ten minutes of undivided attention instead of a thing. The Lover names one concrete need out loud.","note":"These two are spending different currencies, both sincerely. Neither has ever been told the other's is legal tender."},{"a":"strategist","b":"lover","title":"The Mission and the Person","loop":"The Strategist tightens. The Lover soothes, complies, and says nothing about the cost. The Strategist reads compliance as agreement and pushes further. The Lover pleads. The Strategist overrides it as emotional. The Lover shuts down. The Strategist freezes, concluding they cannot be relied on.","aSees":"Someone who agreed and then quietly did not.","bSees":"Someone for whom people are line items.","breaker":"The Strategist asks what this will cost you, and treats the answer as data rather than as resistance. The Lover says no out loud, once, and discovers that the relationship survives it."}];
window.LOW_GIFTS = {"catalyst": {"struggle": "With the Catalyst's fire burning low, you rarely feel an inner demand to confront what is broken. You may tolerate dysfunctional systems and unspoken problems far longer than is healthy, keep the peace when the moment calls for holy disruption, and feel blindsided when change finally forces itself on you. Necessary conflict can feel like failure rather than faithfulness, so hard conversations get postponed until they become harder ones.", "friction": "People who lead with Prophecy can feel overwhelming to you. Their directness lands like an attack and their urgency like recklessness, and you may quietly write them off as harsh—while they read your patience as complicity with what is broken. When they press for the truth behind a problem, you may hear accusation where they intend rescue.", "bridges": ["When a Catalyst confronts, listen for the love of truth underneath the heat—ask “What are you seeing that I’m not?” before defending.", "Practice naming one broken thing out loud each week; borrowed courage grows.", "Don’t ask a Catalyst to soften the message—ask them to help you build what should replace the broken thing."]}, "servant": {"struggle": "With Service running quiet, practical needs don’t call out to you the way they do to others. Tasks pile up or drift to whoever seems willing, the logistics beneath every good idea get underestimated, and the invisible labor that keeps your home, team, or church running can go unnoticed until it stops. You may carry a reputation for being above the mundane that quietly costs you trust.", "friction": "People who lead with Service often feel unseen around you. Your talk-first instinct frustrates their do-first nature; they feel used when their help is assumed and unthanked, while you may find their focus on tasks small when bigger things are on the table. Your unfinished commitments read to them as broken promises.", "bridges": ["Thank the Servant specifically—name the task, not just the person.", "Before casting the next vision, finish one tangible thing you said you’d do.", "Ask “What needs doing?” and take a visible piece of it yourself."]}, "erudite": {"struggle": "With the Erudite’s hunger dimmed, deep study rarely feels worth the time. You may build strong opinions on thin foundations, decide from intuition alone, and grow impatient with the slow work of truly understanding something. That leaves you vulnerable to shallow answers and confident errors—and prone to repeating problems that an evening of honest study would have prevented.", "friction": "People who lead with Teaching can exhaust you. Their questions feel like doubt, their precision like pedantry, their “let me research it” like delay. Meanwhile they experience your speed as carelessness and your certainty as unearned. Conversations stall when nuance—their native language—gets waved away.", "bridges": ["Bring an Erudite into decisions early, not for rubber-stamping afterward.", "Let them fully vet one significant choice each season—and notice what it saves you.", "Ask “What am I missing?” and genuinely wait for the answer."]}, "enthusiast": {"struggle": "With Encouragement running low, affirmation isn’t your reflex. Relationships can run on function rather than celebration, wins slip past unmarked, and the people closest to you may quietly wonder whether you notice them at all. Without a native supply of hope, setbacks weigh heavier and vision is harder to sustain—for you and for anyone following you.", "friction": "People who lead with Encouragement may strike you as noisy or excessive, and their need for affirmation can feel needy. But your reserve reads to them as disapproval, and they wilt in ways you don’t intend. When they celebrate you, you may deflect—which lands as rejection of the very gift they most love to give.", "bridges": ["Name one strength out loud, per person, per gathering. It will feel like too much; it isn’t.", "Receive an Enthusiast’s praise with a simple thank-you instead of a deflection.", "Let celebration count as real work—it is how belonging gets built."]}, "host": {"struggle": "With Giving quiet in you, resources feel like background details rather than ministry. Generosity happens in bursts instead of rhythms, margins and provision go unplanned, and hospitality can feel like a chore—so gathering people defaults to somebody else. Opportunities that needed seed money, a meal, or an open home pass by unclaimed.", "friction": "People who lead with Giving can seem preoccupied with money, logistics, and stewardship, and their carefulness may read to you as stinginess. But your improvidence genuinely stresses them, and when their quiet provision goes unnoticed they feel taken for granted. Asking them to “just trust” without a plan asks them to violate their design.", "bridges": ["Honor stewardship as a spiritual gift, not accounting—thank the Host for what their planning made possible.", "Schedule one act of intentional generosity each month so giving doesn’t depend on mood.", "Invite a Host to build your budget or event plan with you—and watch the anxiety drop."]}, "strategist": {"struggle": "With Leadership’s long view dimmed, the horizon blurs. Seasons turn busy but directionless, goals drift, and you can wake up wondering how you ended up here. Other people’s plans feel confining, so you improvise—and some of those improvisations become messes a simple map would have prevented. Follow-through on multi-step commitments is the quiet casualty.", "friction": "People who lead with Leadership can feel controlling to you—their structures like cages, their questions about “the plan” like tests you didn’t study for. Meanwhile your spontaneity registers to them as a threat to the mission, and your last-minute pivots undo work they invested in. They don’t need you to become them; they need warning before you swerve.", "bridges": ["Give Strategists the courtesy of a heads-up before changing course.", "Borrow their gift: set one 90-day goal and let them help you sequence it.", "Ask “Where is this going?” before you start—then actually aim."]}, "lover": {"struggle": "With Mercy running quiet, the emotional current of a room flows beneath your notice. You reach for solutions when people need presence, miss the wound behind the behavior, and can leave vulnerable people guarded around you without knowing why. Your own feelings, left unprocessed, tend to leak out sideways as irritation or withdrawal.", "friction": "People who lead with Mercy may seem inefficient to you—slow to decide, quick to feel, forever circling back to how everyone is doing. But your fixes land on them as dismissal, and your pace tramples places that needed gentleness. They need safety before solutions; you lead with solutions.", "bridges": ["Ask “Do you want comfort or counsel?” before offering either.", "Sit with someone’s pain for five full minutes before solving anything.", "Let a Lover teach you what listening without fixing looks like—then practice on them."]}};
window.INTENSITY = function(score){
  if (score >= 85) return { label: 'Very High', cls: 'vh' };
  if (score >= 61) return { label: 'High', cls: 'h' };
  if (score >= 41) return { label: 'Medium', cls: 'm' };
  if (score >= 16) return { label: 'Low', cls: 'l' };
  return { label: 'Very Low', cls: 'vl' };
};
/* Official scoring (Unified Scoring Instructions), normalized per gift maximum.
   state = { likert: {qid: 1..5}, fc: {qid: 'a'|'b'}, sjt: {sid: {most: idx, least: idx}} } */
window.computeScores = function(state){
  var Q = window.QUESTIONS, ORDER = window.GIFT_ORDER;
  var raw = {}, likertSub = {}, fcSub = {};
  ORDER.forEach(function(g){ raw[g]=0; likertSub[g]=0; fcSub[g]=0; });
  Q.likert.forEach(function(q){
    var r = state.likert[q.id] || 1;
    raw[q.gift] += (r-1); likertSub[q.gift] += (r-1);
  });
  Q.forcedChoice.forEach(function(q){
    var pick = state.fc[q.id];
    if (pick === 'a') { raw[q.giftA] += 4; fcSub[q.giftA] += 4; }
    if (pick === 'b') { raw[q.giftB] += 4; fcSub[q.giftB] += 4; }
  });
  Q.scenarios.forEach(function(s){
    var st = state.sjt[s.id] || {};
    s.gifts.forEach(function(g, idx){
      if (idx === st.most) raw[g] += 4;
      else if (idx === st.least) raw[g] += 0;
      else raw[g] += 1;
    });
  });
  var scores = {};
  ORDER.forEach(function(g){
    scores[g] = Math.max(0, Math.min(100, Math.round(raw[g] / Q.giftMax[g] * 100)));
  });
  var ranked = ORDER.slice().sort(function(a,b){
    return (scores[b]-scores[a]) || (likertSub[b]-likertSub[a]) || (fcSub[b]-fcSub[a]) || (ORDER.indexOf(a)-ORDER.indexOf(b));
  });
  var top3 = ranked.slice(0,3);
  var tieAtCut = scores[ranked[2]] === scores[ranked[3]];
  var arch = window.ARCHETYPES.find(function(a){
    return a.gifts.slice().sort().join() === top3.slice().sort().join();
  });
  return { scores: scores, raw: raw, ranked: ranked, top3: top3,
           archetype: arch ? arch.slug : null, tieAtCut: tieAtCut, date: new Date().toISOString() };
};
